window.MG_LAZY_DATA["data/lazy/courses/a405-e023a387af8b66c7.json"]={sha256:"e023a387af8b66c77f067828518beb0f58359a463f0c790ca856ffd88fb5388f",value:{"id":"a405","title":"消色差透鏡設計","titleEn":"Achromatic lens design","category":"instruments","kind":"course","summary":"用玻璃色散、光焦度分配與成像驗證，理解雙合透鏡如何降低色差，以及仍須處理的像差與公差。","summaryEn":"Use glass dispersion, optical-power allocation and imaging checks to understand chromatic correction and its remaining aberrations and tolerances.","sourceIds":["v6-achromat-edmund","v6-aberrations-edmund","v6-glass-schott","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"stepCount":44,"estimatedMinutes":1040,"languageCoverage":["zh-TW","en"],"diagram":{"type":"photonics","labels":["波段","玻璃配對","光焦度","組裝","成像驗證"],"labelsEn":["Spectrum","Glass pair","Optical power","Assembly","Image verification"],"original":true,"notToScale":true},"stages":[{"id":"a405-stage01","order":1,"title":"需求與材料","titleEn":"Requirements and materials","description":"先固定波段及共軛，再建立薄透鏡的初步設計。","descriptionEn":"Fix spectrum and conjugates before building a preliminary thin-lens design.","steps":[{"id":"a405-v6-01","order":1,"sequence":1,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v6-aberrations-edmund"],"prerequisiteIds":[],"title":"界定波段、共軛與成像需求","titleEn":"Define spectrum, conjugates and imaging needs","objective":"定義消色差設計要同時服務的波長與物像條件。","objectiveEn":"Define the wavelengths and object-image conditions the achromat must serve.","instruction":"畫出紅、綠、藍三條代表光路和一個共同像面，再分別標記遠方物體與近距物體。為比較選定相同的光圈與成像尺度，避免一邊改波長一邊改物距。","instructionEn":"Draw representative red, green and blue paths and one image plane, then label distant and near objects. Hold aperture and image scale consistent so spectrum and object distance are not changed together.","observation":"單色清楚與多色共同成像是不同要求；物距改變也會改變成像條件。","observationEn":"Single-color sharpness and common multicolor imaging are different requirements; object distance also changes the conjugates.","failure":"若只寫「影像清晰」，便無法區分波段、視場或解析度要求。","failureEn":"A requirement of merely clear imaging cannot distinguish spectrum, field or resolution.","check":"需求表包含波段、物像條件、光圈及需要比較的像面。","checkEn":"Record spectrum, conjugates, aperture and the image plane used for comparison.","knowledge":[{"id":"a405-v6-01-k1","title":"共軛條件","titleEn":"Conjugate conditions","text":"同一透鏡在不同物距下，不一定具有相同像差表現。","textEn":"One lens does not necessarily have the same aberration behavior at different object distances."},{"id":"a405-v6-01-k2","title":"共同像面","titleEn":"Common image plane","text":"消色差評估要比較多個波長，不可只挑最好的一色。","textEn":"Chromatic evaluation compares multiple wavelengths rather than selecting the best-performing color."}],"quiz":{"question":"只展示綠光的清晰影像，能否證明消色差符合需求？","questionEn":"Does one sharp green image prove chromatic requirements are met?","options":["不能，還需在相同條件下比較其他指定波長。","能，只要綠光的焦點正好在感測器平面。","能，只要使用相同玻璃材料，波長不需另測。"],"optionsEn":["No; compare the other specified wavelengths under the same conditions.","Yes, if green focus lies exactly at the sensor plane.","Yes; the same glass removes the need for separate wavelengths."],"answer":0,"explanation":"不能，還需在相同條件下比較其他指定波長。 同一透鏡在不同物距下，不一定具有相同像差表現。","explanationEn":"No; compare the other specified wavelengths under the same conditions. One lens does not necessarily have the same aberration behavior at different object distances."}},{"id":"a405-v6-02","order":2,"sequence":2,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-glass-schott"],"prerequisiteIds":["a405-v6-01"],"title":"閱讀折射率與阿貝數資料","titleEn":"Read refractive-index and Abbe-number data","objective":"區分折射能力與色散的材料指標。","objectiveEn":"Distinguish material measures of refraction and dispersion.","instruction":"從 SCHOTT 資料選兩種玻璃，記下折射率、阿貝數及其光譜線定義。以同一參考線比較，圈出高折射率但不必然低色散的情況。","instructionEn":"Choose two glasses from SCHOTT data and record refractive index, Abbe number and spectral-line definitions. Compare using the same reference line and identify why high index does not necessarily mean low dispersion.","observation":"注意 nd、ne 或不同阿貝數定義不可不經轉換便混用。","observationEn":"Do not mix nd, ne or differently defined Abbe numbers without accounting for their definitions.","failure":"只挑折射率最大的材料，可能使色差配置更困難。","failureEn":"Choosing the highest-index material alone may make chromatic balancing harder.","check":"材料表保留資料來源、參考波長和色散定義。","checkEn":"Retain data source, reference wavelength and dispersion definition in the material table.","knowledge":[{"id":"a405-v6-02-k1","title":"色散指標","titleEn":"Dispersion measure","text":"阿貝數描述指定光譜線間的相對色散，不能等同折射率。","textEn":"Abbe number describes relative dispersion across specified spectral lines, not refractive index itself."},{"id":"a405-v6-02-k2","title":"定義一致","titleEn":"Consistent definitions","text":"比較材料前先對齊參考光譜線與溫度等條件。","textEn":"Align reference spectral lines and conditions such as temperature before comparing materials."}],"quiz":{"question":"兩張表分別使用 nd/Vd 與 ne/Ve，最佳做法是什麼？","questionEn":"Two tables use nd/Vd and ne/Ve respectively. What is the best approach?","options":["只比較數字大小，忽略其參考光譜線。","先核對光譜線定義，再作一致條件比較。","只要兩者皆稱阿貝數，就可以直接互換定義。"],"optionsEn":["Compare numerical values while ignoring their reference spectral lines.","Check spectral-line definitions before making a consistent comparison.","Since both are called Abbe numbers, their definitions are interchangeable."],"answer":1,"explanation":"先核對光譜線定義，再作一致條件比較。 阿貝數描述指定光譜線間的相對色散，不能等同折射率。","explanationEn":"Check spectral-line definitions before making a consistent comparison. Abbe number describes relative dispersion across specified spectral lines, not refractive index itself."}},{"id":"a405-v6-03","order":3,"sequence":3,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-glass-schott","v6-achromat-edmund"],"prerequisiteIds":["a405-v6-02"],"title":"分配正負光焦度","titleEn":"Allocate positive and negative optical power","objective":"以薄透鏡近似建立一階消色差條件。","objectiveEn":"Establish first-order achromatization using a thin-lens approximation.","instruction":"以明確假設的 V1=60、V2=30、總光焦度 10 m⁻¹ 試算。聯立 Φ1+Φ2=10 與 Φ1/V1+Φ2/V2=0，求兩片光焦度，再換算焦距並標註接觸薄透鏡假設。","instructionEn":"Use hypothetical V1=60, V2=30 and total power 10 m⁻¹. Solve Φ1+Φ2=10 and Φ1/V1+Φ2/V2=0, convert the powers to focal lengths and label the contacting-thin-lens assumption.","observation":"所得正片光焦度大於總光焦度，負片抵銷部分光焦度與色散。","observationEn":"The positive element has more power than the total; the negative element cancels part of its power and dispersion.","failure":"混用毫米與公尺會造成千倍焦距錯誤；每行試算保留單位。","failureEn":"Mixing millimeters and meters causes a factor-of-one-thousand focal-length error; keep units on every line.","check":"得到 Φ1=20、Φ2=-10 m⁻¹，且能說明厚度與間隙尚未納入。","checkEn":"Obtain Φ1=20 and Φ2=-10 m⁻¹ and explain that thickness and spacing are not yet included.","knowledge":[{"id":"a405-v6-03-k1","title":"光焦度平衡","titleEn":"Optical-power balance","text":"接觸薄透鏡的總光焦度為各片光焦度之和；色散需另滿足平衡。","textEn":"Contacting thin-lens powers add, while dispersion needs a separate balance."},{"id":"a405-v6-03-k2","title":"近似範圍","titleEn":"Approximation scope","text":"一階試算是起點，不能取代實際厚透鏡追跡。","textEn":"First-order calculation is a starting point, not a replacement for thick-lens ray tracing."}],"quiz":{"question":"本例兩片光焦度應為哪組？","questionEn":"Which pair of powers satisfies the example?","options":["5 與 5 m⁻¹。","10 與 10 m⁻¹。","20 與 -10 m⁻¹。"],"optionsEn":["5 and 5 m⁻¹.","10 and 10 m⁻¹.","20 and -10 m⁻¹."],"answer":2,"explanation":"20 與 -10 m⁻¹。 接觸薄透鏡的總光焦度為各片光焦度之和；色散需另滿足平衡。","explanationEn":"20 and -10 m⁻¹. Contacting thin-lens powers add, while dispersion needs a separate balance."}},{"id":"a405-v6-04","order":4,"sequence":4,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v6-aberrations-edmund","v6-glass-schott"],"prerequisiteIds":["a405-v6-03"],"title":"檢查兩色重合與次級光譜","titleEn":"Check two-color correction and residual spectrum","objective":"理解雙合透鏡仍可能保留中間波長的焦移。","objectiveEn":"Understand why an achromat can retain intermediate-wavelength focus shifts.","instruction":"畫出焦點位置隨波長的示意曲線，將兩個設計波長調至同一焦點，再保留中間波長的偏差。比較「兩點重合」與「整條曲線為零」的差異。","instructionEn":"Draw a schematic focus-versus-wavelength curve, bring two design wavelengths to a common focus and retain an intermediate offset. Compare two-point coincidence with a curve that is zero everywhere.","observation":"兩色對齊不代表所有可見光或紅外線都同樣對齊。","observationEn":"Correcting two colors does not align every visible or infrared wavelength equally.","failure":"將名稱中的「消色差」解讀成零色差，會提出不合理驗收。","failureEn":"Reading achromatic as zero chromatic error creates unrealistic acceptance criteria.","check":"明確標記設計波段和剩餘焦移，而非只畫兩條重合光線。","checkEn":"Mark the design band and remaining focus shift, not only two coincident rays.","knowledge":[{"id":"a405-v6-04-k1","title":"次級光譜","titleEn":"Secondary spectrum","text":"兩波長的一階修正通常仍留下其他波長的殘差。","textEn":"First-order correction at two wavelengths generally leaves residuals at others."},{"id":"a405-v6-04-k2","title":"波段限制","titleEn":"Spectral limits","text":"材料與設計波段共同限定可宣稱的表現。","textEn":"Materials and the design band limit the performance claim."}],"quiz":{"question":"兩個設計波長焦點重合，哪個結論仍不成立？","questionEn":"Two design wavelengths share a focus. Which conclusion is still unsupported?","options":["所有波長都完全沒有色差。","指定兩波長的一階焦移已降低。","仍須查看其他指定波長。"],"optionsEn":["Every wavelength is completely free of chromatic error.","First-order focus separation for the specified pair is reduced.","Other specified wavelengths still need checking."],"answer":0,"explanation":"「所有波長都完全沒有色差」超出兩色焦點重合所能證明的範圍；中間或其他波長仍可能留下次級光譜。","explanationEn":"The claim that every wavelength is free of chromatic error exceeds what two coincident focal positions prove; intermediate and other wavelengths can retain secondary spectrum."}}]},{"id":"a405-stage02","order":2,"title":"形狀與組裝","titleEn":"Shape and assembly","description":"比較表面彎曲、光圈、方向與偏心對成像的影響。","descriptionEn":"Compare curvature, aperture, orientation and decentration effects.","steps":[{"id":"a405-v6-05","order":1,"sequence":5,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v6-aberrations-edmund"],"prerequisiteIds":["a405-v6-04"],"title":"比較曲率配置與透鏡形狀","titleEn":"Compare curvature allocation and lens shape","objective":"分辨相同光焦度下不同形狀的像差。","objectiveEn":"Distinguish aberrations of different shapes with similar power.","instruction":"保持材料與近似總光焦度不變，畫出較對稱與較彎曲的兩組表面。標示中心與邊緣光線，討論為何一階焦距相近仍需進一步追跡。","instructionEn":"Hold materials and approximate total power fixed and draw more symmetric and more strongly bent surface pairs. Mark central and marginal rays and explain why similar paraxial focal length still requires ray tracing.","observation":"表面彎曲的分配會影響邊緣光線，而不只改變透鏡外觀。","observationEn":"Allocation of surface curvature affects marginal rays, not just appearance.","failure":"只保留焦距欄位會漏掉形狀資訊；補上曲率符號和光行方向。","failureEn":"A focal-length-only record omits shape; add curvature signs and propagation direction.","check":"兩個候選均保留表面順序、曲率符號與比較條件。","checkEn":"Retain surface order, curvature signs and comparison conditions for both candidates.","knowledge":[{"id":"a405-v6-05-k1","title":"彎曲自由度","titleEn":"Lens-bending freedom","text":"相近一階光焦度可由不同曲率分配實現。","textEn":"Similar paraxial power can arise from different curvature distributions."},{"id":"a405-v6-05-k2","title":"邊緣光線","titleEn":"Marginal rays","text":"有限光圈下的光線不一定遵循近軸近似。","textEn":"Rays at finite aperture need not follow the paraxial approximation."}],"quiz":{"question":"兩個設計焦距相同，能否因此判定成像品質相同？","questionEn":"Do equal focal lengths prove equal image quality?","options":["能，一階焦距已完整決定有限光圈像差。","不能，表面形狀和有限光圈像差仍可能不同。","能，只要兩者玻璃相同，曲率分配就沒有作用。"],"optionsEn":["Yes; paraxial focal length fully determines finite-aperture aberrations.","No; surface shape and finite-aperture aberrations may differ.","Yes; with identical glass, curvature allocation has no effect."],"answer":1,"explanation":"不能，表面形狀和有限光圈像差仍可能不同。 相近一階光焦度可由不同曲率分配實現。","explanationEn":"No; surface shape and finite-aperture aberrations may differ. Similar paraxial power can arise from different curvature distributions."}},{"id":"a405-v6-06","order":2,"sequence":6,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-aberrations-edmund","v6-achromat-edmund"],"prerequisiteIds":["a405-v6-05"],"title":"區分球差、彗差與色差","titleEn":"Separate spherical aberration, coma and color","objective":"避免用改變波長解釋所有模糊。","objectiveEn":"Avoid attributing every blur to wavelength changes.","instruction":"分別畫單一波長的軸上邊緣光線、離軸光束和多波長軸上光束。為每張圖只改變一種因素：光圈、視場或波長，對應可能的像差類型。","instructionEn":"Draw on-axis marginal rays at one wavelength, an off-axis bundle and a multicolor on-axis bundle. Change only aperture, field or wavelength in each to associate the relevant aberration.","observation":"單色仍有模糊時，不能全歸因於玻璃色散。","observationEn":"Blur that remains in monochromatic light cannot all be attributed to dispersion.","failure":"多因素同時改變會讓診斷失去可比性；返回一因素比較。","failureEn":"Changing multiple factors at once destroys diagnostic comparability; return to one-factor comparisons.","check":"能為三種模糊各指定不同的控制變因與觀察。","checkEn":"Assign a distinct control variable and observation to each blur type.","knowledge":[{"id":"a405-v6-06-k1","title":"像差分類","titleEn":"Aberration classification","text":"色差與單色像差有不同來源，修正一種不代表全部修正。","textEn":"Chromatic and monochromatic aberrations have different origins; correcting one does not correct all."},{"id":"a405-v6-06-k2","title":"控制變因","titleEn":"Controlled variables","text":"波長固定後改變光圈，可把部分幾何像差與色差分開比較。","textEn":"Varying aperture at fixed wavelength helps separate geometric aberrations from color."}],"quiz":{"question":"固定單一波長後，縮小光圈使軸上模糊改善，優先懷疑什麼？","questionEn":"At one wavelength, stopping down improves on-axis blur. What is a plausible concern?","options":["必定是不同波長之間的焦移，即使測試只有單一波長。","必定只有鍍膜透射率改變，光線幾何不需檢查。","與邊緣光線相關的單色像差。"],"optionsEn":["It must be inter-wavelength focus shift even in a single-wavelength test.","It must be coating transmission alone, so ray geometry needs no review.","A monochromatic aberration involving marginal rays."],"answer":2,"explanation":"與邊緣光線相關的單色像差。 色差與單色像差有不同來源，修正一種不代表全部修正。","explanationEn":"A monochromatic aberration involving marginal rays. Chromatic and monochromatic aberrations have different origins; correcting one does not correct all."}},{"id":"a405-v6-07","order":3,"sequence":7,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund"],"prerequisiteIds":["a405-v6-06"],"title":"確認雙合透鏡的安裝方向","titleEn":"Check doublet orientation","objective":"將標示方向與設計共軛對應。","objectiveEn":"Match mounting orientation to the design conjugates.","instruction":"為同一雙合透鏡畫正反兩種安裝圖，固定物距與像面。查閱所選元件的供應商方向說明，將實際朝向與設計條件對應，不假定每款雙合透鏡都可任意翻轉。","instructionEn":"Draw both mounting orientations for one doublet at fixed object distance and image plane. Consult the chosen component’s orientation guidance and match it to design conditions rather than assuming every doublet is reversible.","observation":"焦距可能相近，但翻轉後的像差表現仍可改變。","observationEn":"Focal length may remain similar while aberration performance changes after reversal.","failure":"只看外徑選方向會忽略光學表面配置；回查圖面和共軛。","failureEn":"Choosing orientation by diameter ignores surface arrangement; revisit the drawing and conjugates.","check":"組裝圖有光行方向、元件朝向及依據來源。","checkEn":"Include propagation direction, component orientation and its supporting reference.","knowledge":[{"id":"a405-v6-07-k1","title":"方向與共軛","titleEn":"Orientation and conjugates","text":"透鏡方向應配合設計的物像條件。","textEn":"Lens orientation should match its intended object-image conditions."},{"id":"a405-v6-07-k2","title":"標記追溯","titleEn":"Marking traceability","text":"機械可裝入不等於光學方向正確。","textEn":"Mechanical fit does not establish correct optical orientation."}],"quiz":{"question":"透鏡正反都能裝入鏡筒，下一步應做什麼？","questionEn":"The lens fits the barrel in either direction. What should happen next?","options":["核對元件圖面與設計共軛的方向。","只比較兩面直徑，直徑相同就可任選。","只測一次近軸焦距，就宣稱正反像差相同。"],"optionsEn":["Check orientation against the component drawing and design conjugates.","Compare face diameters only; equal diameters allow either orientation.","Measure paraxial focal length once and declare equal aberrations both ways."],"answer":0,"explanation":"核對元件圖面與設計共軛的方向。 透鏡方向應配合設計的物像條件。","explanationEn":"Check orientation against the component drawing and design conjugates. Lens orientation should match its intended object-image conditions."}},{"id":"a405-v6-08","order":4,"sequence":8,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v6-glass-schott"],"prerequisiteIds":["a405-v6-07"],"title":"評估偏心、傾斜與膠合界面","titleEn":"Evaluate decentration, tilt and the cemented interface","objective":"辨認組裝幾何與材料界面的不同風險。","objectiveEn":"Distinguish assembly geometry from interface-material risks.","instruction":"在剖面上各加入一次偏心、傾斜及膠層不均，保持其他條件不變。畫出可能的光束偏轉或界面問題，並把膠合型與空氣間隔型設計分開記錄。","instructionEn":"Introduce decentration, tilt and uneven cement separately in a cross-section while holding other conditions fixed. Sketch beam deviation or interface issues and record cemented and air-spaced designs separately.","observation":"裝配誤差可能呈現左右不對稱，不能只用軸上單點焦距判斷。","observationEn":"Assembly error can create asymmetry that one on-axis focal-length value misses.","failure":"把空氣間隔直接替換為膠層會改變光學模型，不是單純更換固定方式。","failureEn":"Replacing an air gap with cement changes the optical model, not just the mounting method.","check":"列出至少一項幾何與一項界面材料的驗證。","checkEn":"Identify at least one geometric and one interface-material verification.","knowledge":[{"id":"a405-v6-08-k1","title":"共同光軸","titleEn":"Shared optical axis","text":"雙片的相對光軸與傾角影響組合後的表現。","textEn":"Relative element axes and tilt affect the assembled performance."},{"id":"a405-v6-08-k2","title":"界面介質","titleEn":"Interface medium","text":"膠層或空氣間隙具有光學角色，應納入設計資料。","textEn":"Cement or an air gap has an optical role and belongs in the design data."}],"quiz":{"question":"將空氣間隔雙片直接膠合，為何需重新評估？","questionEn":"Why reassess an air-spaced pair before cementing it?","options":["膠合只改變固定方式，不必修改任何光學模型。","界面介質與間距已改變。","只要兩片外徑相同，空氣與膠層可完全互換。"],"optionsEn":["Cementing changes only mounting and requires no optical-model change.","Interface medium and spacing change.","Equal diameters make air and cement fully interchangeable."],"answer":1,"explanation":"界面介質與間距已改變。 雙片的相對光軸與傾角影響組合後的表現。","explanationEn":"Interface medium and spacing change. Relative element axes and tilt affect the assembled performance."}}]},{"id":"a405-stage03","order":3,"title":"公差與驗收","titleEn":"Tolerances and acceptance","description":"把鍍膜、製造差異與多波長量測整合成可追溯驗收。","descriptionEn":"Combine coatings, manufacturing variation and multiwavelength measurements in traceable acceptance.","steps":[{"id":"a405-v6-09","order":1,"sequence":9,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v6-aberrations-edmund","v6-glass-schott"],"prerequisiteIds":["a405-v6-08"],"title":"區分抗反射鍍膜與色差修正","titleEn":"Separate antireflection coating from chromatic correction","objective":"避免將透光率改善誤當作焦移消除。","objectiveEn":"Avoid mistaking improved transmission for eliminated focal shift.","instruction":"在同一透鏡模型上比較有無抗反射鍍膜的光能路徑，另保留多波長焦點位置圖。分開記錄透射、反射鬼影與焦距，不用亮度替代成像量測。","instructionEn":"Compare light-energy paths with and without an antireflection coating while retaining a separate multicolor focus diagram. Record transmission, reflected ghosts and focal position independently.","observation":"影像變亮或反光減少，不必然代表色差已降低。","observationEn":"A brighter image or reduced reflection does not necessarily indicate lower chromatic aberration.","failure":"超出鍍膜設計波段的表現不可從單一波長外推。","failureEn":"Do not extrapolate one wavelength’s coating performance beyond its design band.","check":"驗收表分開列出光譜透射與多色焦移。","checkEn":"Separate spectral transmission and multicolor focus shift in acceptance records.","knowledge":[{"id":"a405-v6-09-k1","title":"反射與折射","titleEn":"Reflection and refraction","text":"抗反射鍍膜主要控制界面反射；雙合材料配置負責主要色差平衡。","textEn":"Antireflection coatings primarily control interface reflection; doublet material allocation provides the main chromatic balance."},{"id":"a405-v6-09-k2","title":"亮度誤判","titleEn":"Brightness misinterpretation","text":"亮度受到光源與曝光影響，不能單獨代表解析品質。","textEn":"Brightness depends on illumination and exposure and is not an independent measure of resolution."}],"quiz":{"question":"鍍膜後影像更亮，是否足以證明兩色焦點更接近？","questionEn":"The coated lens produces a brighter image. Does that prove closer two-color focus?","options":["足夠，較高透射率必然代表較小軸向色差。","足夠，只要鍍膜顏色符合設計波段。","不足，需另測多波長焦點。"],"optionsEn":["Yes; higher transmission necessarily means smaller axial color.","Yes, if the coating’s visible color matches the design band.","No; multiwavelength focus needs separate measurement."],"answer":2,"explanation":"不足，需另測多波長焦點。 抗反射鍍膜主要控制界面反射；雙合材料配置負責主要色差平衡。","explanationEn":"No; multiwavelength focus needs separate measurement. Antireflection coatings primarily control interface reflection; doublet material allocation provides the main chromatic balance."}},{"id":"a405-v6-10","order":2,"sequence":10,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-glass-schott","v6-aberrations-edmund"],"prerequisiteIds":["a405-v6-09"],"title":"建立尺寸與材料的公差敏感度","titleEn":"Build tolerance sensitivity for geometry and glass","objective":"找出值得優先控制的設計變因。","objectiveEn":"Identify design variables that deserve priority control.","instruction":"建立曲率、厚度、間距、折射率與偏心五欄。用模型或來源資料逐一施加小變化，記錄焦位或影像指標的變化方向；明確註明不是工廠統計分布。","instructionEn":"Create columns for curvature, thickness, spacing, refractive index and decentration. Apply small changes individually in a model or referenced data and record response direction, explicitly distinguishing this from factory statistics.","observation":"相同百分比變化對不同變因，不一定造成相同影像影響。","observationEn":"Equal percentage changes in different variables need not produce equal image effects.","failure":"把單因子結果直接相加成量產良率會超出資料能力。","failureEn":"Turning one-factor results directly into production yield exceeds the evidence.","check":"指出最敏感的候選變因及其比較尺度，保留尚未評估的耦合。","checkEn":"Identify candidate sensitive variables and comparison scales while retaining untested couplings.","knowledge":[{"id":"a405-v6-10-k1","title":"敏感度","titleEn":"Sensitivity","text":"公差評估關心輸入偏差如何傳到成像結果。","textEn":"Tolerance analysis asks how input deviations propagate into imaging results."},{"id":"a405-v6-10-k2","title":"分布假設","titleEn":"Distribution assumptions","text":"良率推估另需合理的製造分布及變因相關性。","textEn":"Yield estimates additionally need defensible manufacturing distributions and correlations."}],"quiz":{"question":"只有單因子敏感度表，能否直接宣稱量產良率？","questionEn":"Can a one-factor sensitivity table directly establish production yield?","options":["不能，仍缺製造分布和相關性資料。","能，把各變因造成的偏差百分比平均即可。","能，單因子分析已包含變因之間的相關性。"],"optionsEn":["No; manufacturing distributions and correlations are missing.","Yes; average the deviation percentages from all variables.","Yes; one-factor analysis already includes inter-variable correlations."],"answer":0,"explanation":"不能，仍缺製造分布和相關性資料。 公差評估關心輸入偏差如何傳到成像結果。","explanationEn":"No; manufacturing distributions and correlations are missing. Tolerance analysis asks how input deviations propagate into imaging results."}},{"id":"a405-v6-11","order":3,"sequence":11,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v6-aberrations-edmund"],"prerequisiteIds":["a405-v6-10"],"title":"比較多波長焦點與離軸影像","titleEn":"Compare multicolor focus and off-axis images","objective":"用一致條件檢查軸上與視場邊緣。","objectiveEn":"Check on-axis and field-edge behavior under consistent conditions.","instruction":"用紙上光線模型或自行取得的合適測量資料，固定物體、光圈與參考位置；分別記錄指定波長的最佳焦位，再在共同像面比較中心和邊緣。","instructionEn":"Using a paper ray model or suitable measurements you obtain, hold object, aperture and reference position fixed. Record best focus for each wavelength, then compare center and edge at one common image plane.","observation":"各色各自重新對焦可掩蓋共同像面上的實際色差。","observationEn":"Refocusing separately for each color can hide the actual chromatic error at a shared image plane.","failure":"更改曝光或物距而未記錄，會破壞不同影像之間的比較。","failureEn":"Unrecorded exposure or object-distance changes undermine comparisons.","check":"結果同時包含各色最佳焦位與共同像面表現。","checkEn":"Include both per-color best-focus positions and common-plane performance.","knowledge":[{"id":"a405-v6-11-k1","title":"共同條件比較","titleEn":"Like-for-like comparison","text":"驗收需與實際使用條件一致，不能為每個結果換一組最佳條件。","textEn":"Acceptance should match use conditions rather than optimize conditions independently for each result."},{"id":"a405-v6-11-k2","title":"視場取樣","titleEn":"Field sampling","text":"軸上良好不保證離軸同樣良好。","textEn":"Good on-axis performance does not guarantee good off-axis performance."}],"quiz":{"question":"為每種顏色各自重新對焦後都很清楚，還缺什麼？","questionEn":"Every color is sharp after separate refocusing. What evidence is missing?","options":["只比較各色在自己的最佳像面所得影像。","在同一像面上的多色比較。","只比較總透光率，無需保留焦位差。"],"optionsEn":["Compare each color only at its own best image plane.","A multicolor comparison at one image plane.","Compare total transmission without retaining focus offsets."],"answer":1,"explanation":"在同一像面上的多色比較。 驗收需與實際使用條件一致，不能為每個結果換一組最佳條件。","explanationEn":"A multicolor comparison at one image plane. Acceptance should match use conditions rather than optimize conditions independently for each result."}},{"id":"a405-v6-12","order":4,"sequence":12,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v6-aberrations-edmund","v6-glass-schott"],"prerequisiteIds":["a405-v6-11"],"title":"整理光學組件的驗收與追溯","titleEn":"Assemble optical acceptance and traceability","objective":"讓材料、設計版本與實測條件可互相對應。","objectiveEn":"Link materials, design revision and measurement conditions.","instruction":"把玻璃資料、表面順序、方向、公差與成像結果組成一份交接表。加入一個可接受殘差與一個超限案例，分別寫出接受理由及需要改善的變因。","instructionEn":"Combine glass data, surface order, orientation, tolerances and imaging results in a handoff record. Add an acceptable residual and an out-of-limit case, stating acceptance reasoning and the variable to investigate.","observation":"聲稱「完全不散色」通常超出有限波段與有限公差的證據。","observationEn":"A claim of absolutely no dispersion generally exceeds evidence limited by spectrum and tolerances.","failure":"若測試版本與製造圖面不同，先修正版本對應再作判定。","failureEn":"If tested and manufactured revisions differ, restore revision correspondence before judgment.","check":"交付文件說明適用波段、殘餘像差、組裝方向及未驗證條件。","checkEn":"State the applicable band, residual aberrations, mounting orientation and unverified conditions.","knowledge":[{"id":"a405-v6-12-k1","title":"規格化性能","titleEn":"Specified performance","text":"工程驗收依明確條件下的性能，而不是無限範圍的完美宣稱。","textEn":"Engineering acceptance uses performance under stated conditions rather than unlimited perfection claims."},{"id":"a405-v6-12-k2","title":"版本控制","titleEn":"Revision control","text":"材料批次、設計處方與測試條件需可追溯到同一組件。","textEn":"Material lot, prescription and test conditions should trace to the same assembly."}],"quiz":{"question":"哪個交付描述最可驗證？","questionEn":"Which delivery statement is most verifiable?","options":["在未指定波段下，單一焦距正確即代表全面合格。","外徑與中心厚度合格即可取代所有成像驗收。","在列明波段與共軛下符合指定焦移和成像要求。"],"optionsEn":["Correct focal length alone proves complete compliance without a specified spectrum.","Diameter and center-thickness compliance replace all imaging acceptance.","Meets stated focus-shift and imaging requirements over the listed band and conjugates."],"answer":2,"explanation":"在列明波段與共軛下符合指定焦移和成像要求。 工程驗收依明確條件下的性能，而不是無限範圍的完美宣稱。","explanationEn":"Meets stated focus-shift and imaging requirements over the listed band and conjugates. Engineering acceptance uses performance under stated conditions rather than unlimited perfection claims."}}]},{"id":"a405-v12-s1","title":"系統邊界與物理原理","titleEn":"System boundaries and physical principles","description":"本階段聚焦「部分色散與三片式複消色差解」與「熱離焦與光熱係數」：先建立機制與定量模型，再設計驗證並診斷失效。","descriptionEn":"This stage covers \"Partial dispersion and the three-glass apochromatic solution\" and \"Thermal defocus and the opto-thermal coefficient\": build the mechanism and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"a405-v12-01","title":"部分色散與三片式複消色差解：原理與系統邊界","titleEn":"Partial dispersion and the three-glass apochromatic solution: mechanism and system boundary","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v6-12"],"objective":"說明「三片式複消色差組」如何決定消色差透鏡設計的關鍵性能，並畫出其輸入、輸出與邊界。","objectiveEn":"Explain how “Three-glass apochromatic group” determines the key performance of “Achromatic lens design”, and map its inputs, outputs and boundaries.","instruction":"兩片玻璃的消色差只能讓 C 與 F 線共焦；一般玻璃的相對部分色散落在正常線 P_gF ≈ 0.6438 − 0.001682·ν_d 上，其他波長仍各自聚焦，留下二級光譜。要讓第三個波長也共焦，需同時滿足三個條件：總光焦度 Σφᵢ = φ、一級色差 Σφᵢ/νᵢ = 0、二級色差 Σφᵢ·Pᵢ/νᵢ = 0。三種玻璃在 (1/ν, P) 平面上必須圍成三角形，三角形面積越小，各片光焦度越大；正常線之外的異常色散玻璃（如 N-FK51A 的 ΔP_gF = +0.034、N-KZFS4 的 −0.010）可以把三角形撐開。三片式的代價是單片光焦度變大、曲率變陡，高階像差與定心敏感度隨之上升。 師傅任務：以方塊圖畫出能量或訊號通過「三片式複消色差組」的路徑，標出哪些量由設計決定、哪些由環境或製造決定，再用三句話寫出機制摘要。","instructionEn":"A two-glass achromat can only bring the C and F lines to a common focus; ordinary glasses have relative partial dispersions on the normal line P_gF ≈ 0.6438 − 0.001682·ν_d, so other wavelengths still focus elsewhere and leave the secondary spectrum. Bringing a third wavelength to the same focus requires three conditions at once: total power Σφᵢ = φ, zero primary colour Σφᵢ/νᵢ = 0 and zero secondary colour Σφᵢ·Pᵢ/νᵢ = 0. The three glasses must form a triangle in the (1/ν, P) plane, and the smaller its area the larger the individual element powers; anomalous-dispersion glasses off the normal line, such as N-FK51A with ΔP_gF = +0.034 and N-KZFS4 with −0.010, open the triangle up. The price of a triplet is larger element powers and steeper curves, so higher-order aberrations and centring sensitivity grow. Mentor task: draw a block diagram of the energy or signal path through “Three-glass apochromatic group”, mark which quantities are fixed by design and which by environment or fabrication, then summarise the mechanism in three sentences.","observation":"量級提示：由 Sellmeier 係數算得 N-FK51A（ν = 84.47、P = 0.5359）、N-KZFS4（44.49、0.5590）、N-SF5（32.25、0.5984）。","observationEn":"Order-of-magnitude cue: From Sellmeier coefficients: N-FK51A (ν = 84.47, P = 0.5359), N-KZFS4 (44.49, 0.5590) and N-SF5 (32.25, 0.5984).","failure":"常見誤解：「只要兩片玻璃的阿貝數差夠大，就能完全消除二級光譜。」這個說法忽略了上述機制；請在方塊圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A large enough Abbe-number difference between two glasses eliminates the secondary spectrum.\" It ignores the mechanism above; mark on your block diagram where it breaks down.","check":"方塊圖標明「三片式複消色差組」的輸入、輸出與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The block diagram shows inputs, outputs and boundaries of “Three-glass apochromatic group”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"a405-v12-01-k1","title":"部分色散與三片式複消色差解","titleEn":"Partial dispersion and the three-glass apochromatic solution","text":"兩片玻璃的消色差只能讓 C 與 F 線共焦；一般玻璃的相對部分色散落在正常線 P_gF ≈ 0.6438 − 0.001682·ν_d 上，其他波長仍各自聚焦，留下二級光譜。要讓第三個波長也共焦，需同時滿足三個條件：總光焦度 Σφᵢ = φ、一級色差 Σφᵢ/νᵢ = 0、二級色差 Σφᵢ·Pᵢ/νᵢ = 0。","textEn":"A two-glass achromat can only bring the C and F lines to a common focus; ordinary glasses have relative partial dispersions on the normal line P_gF ≈ 0.6438 − 0.001682·ν_d, so other wavelengths still focus elsewhere and leave the secondary spectrum. Bringing a third wavelength to the same focus requires three conditions at once: total power Σφᵢ = φ, zero primary colour Σφᵢ/νᵢ = 0 and zero secondary colour Σφᵢ·Pᵢ/νᵢ = 0.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要兩片玻璃的阿貝數差夠大，就能完全消除二級光譜。 正確的工程判斷必須回到機制與量級。","textEn":"Misconception: A large enough Abbe-number difference between two glasses eliminates the secondary spectrum. Sound engineering judgement goes back to mechanism and magnitude.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"關於「部分色散與三片式複消色差解」，下列哪一項敘述正確？","questionEn":"Which statement about \"Partial dispersion and the three-glass apochromatic solution\" is correct?","options":["只要兩片玻璃的阿貝數差夠大，就能完全消除二級光譜。","兩片玻璃的消色差只能讓 C 與 F 線共焦。","玻璃的熱膨脹很小，所以溫度變化不會讓焦點移動。"],"optionsEn":["A large enough Abbe-number difference between two glasses eliminates the secondary spectrum.","A two-glass achromat can only bring the C and F lines to a common focus.","Glass expands so little that temperature changes cannot move the focus."],"answer":1,"explanation":"兩片玻璃的消色差只能讓 C 與 F 線共焦；一般玻璃的相對部分色散落在正常線 P_gF ≈ 0.6438 − 0.001682·ν_d 上，其他波長仍各自聚焦，留下二級光譜。 其餘選項是常見誤解。","explanationEn":"A two-glass achromat can only bring the C and F lines to a common focus; ordinary glasses have relative partial dispersions on the normal line P_gF ≈ 0.6438 − 0.001682·ν_d, so other wavelengths still focus elsewhere and leave the secondary spectrum. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":13},{"id":"a405-v12-02","title":"部分色散與三片式複消色差解：定量估算","titleEn":"Partial dispersion and the three-glass apochromatic solution: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-01"],"objective":"以數值模型估算「三片式複消色差組」的關鍵量，並判斷參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Three-glass apochromatic group” with a numerical model and judge the direction and size of changes when a parameter moves.","instruction":"依下列模型逐步重算：由 Sellmeier 係數算得 N-FK51A（ν = 84.47、P = 0.5359）、N-KZFS4（44.49、0.5590）、N-SF5（32.25、0.5984）。f = 100 mm 解三式：φ₁ = 2.576φ（f₁ = 38.8 mm）、φ₂ = −2.153φ（f₂ = −46.4 mm）、φ₃ = 0.577φ（f₃ = 173.3 mm）；以實際折射率逐線計算，C、F、g 焦點都落在 d 焦點 0.15 µm 以內。對照 N-BK7/F2 雙合：C、F 在 d 後 50 µm、g 在 223 µm；但三片式 Σ|φᵢ| = 5.31φ，雙合只有 3.62φ。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係。","instructionEn":"Recalculate step by step: From Sellmeier coefficients: N-FK51A (ν = 84.47, P = 0.5359), N-KZFS4 (44.49, 0.5590) and N-SF5 (32.25, 0.5984). Solving the three equations for f = 100 mm gives φ₁ = 2.576φ (f₁ = 38.8 mm), φ₂ = −2.153φ (f₂ = −46.4 mm) and φ₃ = 0.577φ (f₃ = 173.3 mm); tracing with real indices line by line puts the C, F and g foci within 0.15 µm of the d focus. For comparison an N-BK7/F2 doublet leaves C and F 50 µm behind d and g at 223 µm, but the triplet carries Σ|φᵢ| = 5.31φ against 3.62φ for the doublet. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, and state whether the dependence is linear, quadratic or steeper.","observation":"如何核對：以實際熔煉批的熔次資料（n_d、ν_d、P_gF）取代型錄值重新解光焦度；組裝後用單色儀或窄帶濾光片在 C、d、F、g 各波長量軸向最佳焦點，確認焦點散佈小於景深，並與模型的 0.15 µm 等級殘差比較；同時量各片偏心，因為大光焦度讓同樣的偏心產生更大的彗差。","observationEn":"How to cross-check: Re-solve the powers with melt-sheet data (n_d, ν_d, P_gF) from the actual glass lots instead of catalogue values; after assembly measure the axial best focus at C, d, F and g with a monochromator or narrow-band filters, confirm the spread is smaller than the depth of focus and compare with the modelled 0.15 µm-level residual; measure element decentration as well, because large powers turn the same decentre into more coma.","failure":"計算陷阱：單位換算錯誤、把教學假設當成設備規格，或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit conversion slips, treating teaching assumptions as equipment specifications, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與物理解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with a physical explanation.","knowledge":[{"id":"a405-v12-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"由 Sellmeier 係數算得 N-FK51A（ν = 84.47、P = 0.5359）、N-KZFS4（44.49、0.5590）、N-SF5（32.25、0.5984）。f = 100 mm 解三式：φ₁ = 2.576φ（f₁ = 38.8 mm）、φ₂ = −2.153φ（f₂ = −46.4 mm）、φ₃ = 0.577φ（f₃ = 173.3 mm）；以實際折射率逐線計算，C、F、g 焦點都落在 d 焦點 0.15 µm 以內。對照 N-BK7/F2 雙合：C、F 在 d 後 50 µm、g 在 223 µm；但三片式 Σ|φᵢ| = 5.31φ，雙合只有 3.62φ。","textEn":"From Sellmeier coefficients: N-FK51A (ν = 84.47, P = 0.5359), N-KZFS4 (44.49, 0.5590) and N-SF5 (32.25, 0.5984). Solving the three equations for f = 100 mm gives φ₁ = 2.576φ (f₁ = 38.8 mm), φ₂ = −2.153φ (f₂ = −46.4 mm) and φ₃ = 0.577φ (f₃ = 173.3 mm); tracing with real indices line by line puts the C, F and g foci within 0.15 µm of the d focus. For comparison an N-BK7/F2 doublet leaves C and F 50 µm behind d and g at 223 µm, but the triplet carries Σ|φᵢ| = 5.31φ against 3.62φ for the doublet.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設；套用到實際設備前，必須重新取得規格、操作條件與不確定度。","textEn":"These numbers are teaching assumptions; before applying them to real equipment, obtain the actual specifications, operating conditions and uncertainties.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"依「部分色散與三片式複消色差解」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Partial dispersion and the three-glass apochromatic solution\", which statement holds?","options":["鏡片拋光到正確曲率後自然就是同心的，不需要另外定心。","HeNe 干涉儀量到的波前合格，就代表整個可見光波段都合格。","由 Sellmeier 係數算得 N-FK51A（ν = 84.47、P = 0.5359）、N-KZFS4（44.49、0.5590）、N-SF5（32.25、0.5984）。"],"optionsEn":["A lens polished to the right radii is automatically centred.","A wavefront pass at 632.8 nm means the lens passes across the visible band.","From Sellmeier coefficients: N-FK51A (ν = 84.47, P = 0.5359), N-KZFS4 (44.49, 0.5590) and N-SF5 (32.25, 0.5984)."],"answer":2,"explanation":"由 Sellmeier 係數算得 N-FK51A（ν = 84.47、P = 0.5359）、N-KZFS4（44.49、0.5590）、N-SF5（32.25、0.5984）。 重算時請保留單位。","explanationEn":"From Sellmeier coefficients: N-FK51A (ν = 84.47, P = 0.5359), N-KZFS4 (44.49, 0.5590) and N-SF5 (32.25, 0.5984). Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":14},{"id":"a405-v12-03","title":"部分色散與三片式複消色差解：量測與驗證","titleEn":"Partial dispersion and the three-glass apochromatic solution: measurement and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-02"],"objective":"設計一項可重複的量測，驗證「三片式複消色差組」是否符合模型預期，並訂出允收準則。","objectiveEn":"Design a repeatable measurement that verifies whether “Three-glass apochromatic group” meets the model expectation, and set acceptance criteria.","instruction":"以實際熔煉批的熔次資料（n_d、ν_d、P_gF）取代型錄值重新解光焦度；組裝後用單色儀或窄帶濾光片在 C、d、F、g 各波長量軸向最佳焦點，確認焦點散佈小於景深，並與模型的 0.15 µm 等級殘差比較；同時量各片偏心，因為大光焦度讓同樣的偏心產生更大的彗差。 師傅任務：把上述方法寫成量測計畫，列出儀器、基準件或參考樣品、步驟、比較對象與允收準則，並估計三項主要不確定度來源。","instructionEn":"Re-solve the powers with melt-sheet data (n_d, ν_d, P_gF) from the actual glass lots instead of catalogue values; after assembly measure the axial best focus at C, d, F and g with a monochromator or narrow-band filters, confirm the spread is smaller than the depth of focus and compare with the modelled 0.15 µm-level residual; measure element decentration as well, because large powers turn the same decentre into more coma. Mentor task: turn this into a measurement plan listing instruments, reference artefacts or samples, procedure, comparison baseline and acceptance criteria, and estimate the three largest uncertainty contributions.","observation":"注意干擾：FK51A 類氟磷冠玻璃硬度低、膨脹係數大、耐候性差，拋光或膠合時容易出現裂紋與表面污斑；若沿用型錄 P_gF 而不看熔次資料，三色共焦點偏移，實際殘餘色差可能比設計大一個數量級，而大光焦度也讓軸上彗差對定心誤差極為敏感。","observationEn":"Watch for interference: Fluorophosphate crowns of the FK51A type are soft, high-expansion and weather poorly, so they crack or stain during polishing or cementing; using catalogue P_gF instead of melt data shifts the three-colour focus so the real residual colour can be an order of magnitude above design, and the large powers make on-axis coma extremely sensitive to centring error.","failure":"驗證陷阱：只量一次、沒有可追溯的基準，或不記錄環境條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Verification traps: a single measurement, no traceable reference, or unrecorded environmental conditions make real deviations indistinguishable from measurement error.","check":"提交量測計畫：儀器、基準、步驟、允收準則與不確定度預算，並說明如何判定合格或不合格。","checkEn":"Submit the measurement plan: instruments, reference, procedure, acceptance criteria and uncertainty budget, with the pass/fail decision rule.","knowledge":[{"id":"a405-v12-03-k1","title":"驗證方法","titleEn":"Verification method","text":"以實際熔煉批的熔次資料（n_d、ν_d、P_gF）取代型錄值重新解光焦度；組裝後用單色儀或窄帶濾光片在 C、d、F、g 各波長量軸向最佳焦點，確認焦點散佈小於景深，並與模型的 0.15 µm 等級殘差比較；同時量各片偏心，因為大光焦度讓同樣的偏心產生更大的彗差。","textEn":"Re-solve the powers with melt-sheet data (n_d, ν_d, P_gF) from the actual glass lots instead of catalogue values; after assembly measure the axial best focus at C, d, F and g with a monochromator or narrow-band filters, confirm the spread is smaller than the depth of focus and compare with the modelled 0.15 µm-level residual; measure element decentration as well, because large powers turn the same decentre into more coma.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-03-k2","title":"允收與不確定度","titleEn":"Acceptance and uncertainty","text":"允收準則必須在量測前訂定，並與擴充不確定度一起陳述；比較基準需可追溯。","textEn":"Acceptance criteria are fixed before measuring and stated together with expanded uncertainty; the comparison reference must be traceable.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"要驗證「部分色散與三片式複消色差解」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Partial dispersion and the three-glass apochromatic solution\"?","options":["以實際熔煉批的熔次資料（n_d、ν_d、P_gF）取代型錄值重新解光焦度。","量測時不必記錄溫度、振動與時間等條件，因為它們不會影響結果。","只要鍍了抗反射膜，就不會出現鬼影。"],"optionsEn":["Re-solve the powers with melt-sheet data (n_d, ν_d, P_gF) from the actual glass lots instead of catalogue values.","Temperature, vibration and timing need not be recorded because they cannot affect the result.","Once an antireflection coating is applied, ghosts cannot appear."],"answer":0,"explanation":"以實際熔煉批的熔次資料（n_d、ν_d、P_gF）取代型錄值重新解光焦度；組裝後用單色儀或窄帶濾光片在 C、d、F、g 各波長量軸向最佳焦點，確認焦點散佈小於景深，並與模型的 0.15 µm 等級殘差比較；同時量各片偏心，因為大光焦度讓同樣的偏心產生更大的彗差。 驗證需要基準、重複性與允收準則。","explanationEn":"Re-solve the powers with melt-sheet data (n_d, ν_d, P_gF) from the actual glass lots instead of catalogue values; after assembly measure the axial best focus at C, d, F and g with a monochromator or narrow-band filters, confirm the spread is smaller than the depth of focus and compare with the modelled 0.15 µm-level residual; measure element decentration as well, because large powers turn the same decentre into more coma. Verification needs a reference, repeatability and acceptance criteria."},"unit":1,"unitFacet":"verification","order":3,"sequence":15},{"id":"a405-v12-04","title":"部分色散與三片式複消色差解：失效診斷","titleEn":"Partial dispersion and the three-glass apochromatic solution: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-03"],"objective":"從症狀倒推「三片式複消色差組」的失效原因，提出能區分原因的檢查與矯正措施。","objectiveEn":"Work back from symptoms to the failure causes of “Three-glass apochromatic group” and propose discriminating checks and corrective actions.","instruction":"FK51A 類氟磷冠玻璃硬度低、膨脹係數大、耐候性差，拋光或膠合時容易出現裂紋與表面污斑；若沿用型錄 P_gF 而不看熔次資料，三色共焦點偏移，實際殘餘色差可能比設計大一個數量級，而大光焦度也讓軸上彗差對定心誤差極為敏感。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測，以及矯正與預防措施；並說明此失效如何影響整個系統的性能、良率或安全。","instructionEn":"Fluorophosphate crowns of the FK51A type are soft, high-expansion and weather poorly, so they crack or stain during polishing or cementing; using catalogue P_gF instead of melt data shifts the three-colour focus so the real residual colour can be an order of magnitude above design, and the large powers make on-axis coma extremely sensitive to centring error. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system performance, yield or safety.","observation":"連結機制：三片式的代價是單片光焦度變大、曲率變陡，高階像差與定心敏感度隨之上升。","observationEn":"Link to the mechanism: The price of a triplet is larger element powers and steeper curves, so higher-order aberrations and centring sensitivity grow.","failure":"誤判風險：若相信「只要兩片玻璃的阿貝數差夠大，就能完全消除二級光譜。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A large enough Abbe-number difference between two glasses eliminates the secondary spectrum.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，並指出哪一項量測能最快確認根因、如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement that confirms the root cause fastest, and state how recurrence is prevented.","knowledge":[{"id":"a405-v12-04-k1","title":"失效模式","titleEn":"Failure mode","text":"FK51A 類氟磷冠玻璃硬度低、膨脹係數大、耐候性差，拋光或膠合時容易出現裂紋與表面污斑；若沿用型錄 P_gF 而不看熔次資料，三色共焦點偏移，實際殘餘色差可能比設計大一個數量級，而大光焦度也讓軸上彗差對定心誤差極為敏感。","textEn":"Fluorophosphate crowns of the FK51A type are soft, high-expansion and weather poorly, so they crack or stain during polishing or cementing; using catalogue P_gF instead of melt data shifts the three-colour focus so the real residual colour can be an order of magnitude above design, and the large powers make on-axis coma extremely sensitive to centring error.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測確認；只更換零件或放寬參數可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement; merely swapping parts or relaxing limits can mask the problem.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"在「部分色散與三片式複消色差解」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Partial dispersion and the three-glass apochromatic solution\" misbehaves, which diagnosis is most reasonable?","options":["所有異常都來自操作人員失誤，系統設計不需要檢討。","FK51A 類氟磷冠玻璃硬度低、膨脹係數大、耐候性差，拋光或膠合時容易出現裂紋與表面污斑。","玻璃的熱膨脹很小，所以溫度變化不會讓焦點移動。"],"optionsEn":["Every anomaly is operator error, so the system design never needs review.","Fluorophosphate crowns of the FK51A type are soft, high-expansion and weather poorly, so they crack or stain during polishing or cementing.","Glass expands so little that temperature changes cannot move the focus."],"answer":1,"explanation":"FK51A 類氟磷冠玻璃硬度低、膨脹係數大、耐候性差，拋光或膠合時容易出現裂紋與表面污斑；若沿用型錄 P_gF 而不看熔次資料，三色共焦點偏移，實際殘餘色差可能比設計大一個數量級，而大光焦度也讓軸上彗差對定心誤差極為敏感。 需以量測區分可能原因。","explanationEn":"Fluorophosphate crowns of the FK51A type are soft, high-expansion and weather poorly, so they crack or stain during polishing or cementing; using catalogue P_gF instead of melt data shifts the three-colour focus so the real residual colour can be an order of magnitude above design, and the large powers make on-axis coma extremely sensitive to centring error. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":16},{"id":"a405-v12-05","title":"熱離焦與光熱係數：原理與系統邊界","titleEn":"Thermal defocus and the opto-thermal coefficient: mechanism and system boundary","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-04"],"objective":"說明「熱光係數與鏡筒膨脹」如何決定消色差透鏡設計的關鍵性能，並畫出其輸入、輸出與邊界。","objectiveEn":"Explain how “Thermo-optic coefficient and barrel expansion” determines the key performance of “Achromatic lens design”, and map its inputs, outputs and boundaries.","instruction":"溫度同時改變折射率（dn/dT）與鏡片尺寸（膨脹係數 α），薄透鏡在空氣中的焦距變化率為 (1/f)·df/dT = α − (dn/dT)/(n − 1)，稱為光熱係數。型錄的 dn/dT 是相對於空氣的值，SCHOTT 另以 G = α(n − 1) + dn/dT 表示玻璃的熱光常數。雙合透鏡的光熱係數按各片光焦度加權相加；同時鏡片到感測器之間的鏡筒或隔圈以 α_h·L 伸長。無熱化設計要讓像面移動與機構伸長相等，即 γ·f ≈ α_h·L，這對戶外相機、車載與太空光學尤其關鍵。 師傅任務：以方塊圖畫出能量或訊號通過「熱光係數與鏡筒膨脹」的路徑，標出哪些量由設計決定、哪些由環境或製造決定，再用三句話寫出機制摘要。","instructionEn":"Temperature changes both the refractive index (dn/dT) and the lens dimensions (expansion coefficient α), and for a thin lens in air the focal-length change rate is (1/f)·df/dT = α − (dn/dT)/(n − 1), the opto-thermal coefficient. Catalogue dn/dT values are relative to air, and SCHOTT also expresses the thermo-optical constant as G = α(n − 1) + dn/dT. A doublet's opto-thermal coefficient is the power-weighted sum of its elements, while the barrel or spacer between lens and sensor grows by α_h·L. Athermal design makes image-plane motion equal mount growth, γ·f ≈ α_h·L, which is critical for outdoor, automotive and space cameras. Mentor task: draw a block diagram of the energy or signal path through “Thermo-optic coefficient and barrel expansion”, mark which quantities are fixed by design and which by environment or fabrication, then summarise the mechanism in three sentences.","observation":"量級提示：N-BK7：α = 7.1 ppm/K、相對 dn/dT = 3.0 ppm/K（e 線）、n_e − 1 = 0.5187，γ = 7.1 − 5.78 = 1.32 ppm/K；F2：8.2 − 4.4/0.6241 = 1.15 ppm/K。","observationEn":"Order-of-magnitude cue: N-BK7: α = 7.1 ppm/K, relative dn/dT = 3.0 ppm/K (e-line), n_e − 1 = 0.5187, so γ = 7.1 − 5.78 = 1.32 ppm/K; F2: 8.2 − 4.4/0.6241 = 1.15 ppm/K.","failure":"常見誤解：「玻璃的熱膨脹很小，所以溫度變化不會讓焦點移動。」這個說法忽略了上述機制；請在方塊圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Glass expands so little that temperature changes cannot move the focus.\" It ignores the mechanism above; mark on your block diagram where it breaks down.","check":"方塊圖標明「熱光係數與鏡筒膨脹」的輸入、輸出與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The block diagram shows inputs, outputs and boundaries of “Thermo-optic coefficient and barrel expansion”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"a405-v12-05-k1","title":"熱離焦與光熱係數","titleEn":"Thermal defocus and the opto-thermal coefficient","text":"溫度同時改變折射率（dn/dT）與鏡片尺寸（膨脹係數 α），薄透鏡在空氣中的焦距變化率為 (1/f)·df/dT = α − (dn/dT)/(n − 1)，稱為光熱係數。型錄的 dn/dT 是相對於空氣的值，SCHOTT 另以 G = α(n − 1) + dn/dT 表示玻璃的熱光常數。","textEn":"Temperature changes both the refractive index (dn/dT) and the lens dimensions (expansion coefficient α), and for a thin lens in air the focal-length change rate is (1/f)·df/dT = α − (dn/dT)/(n − 1), the opto-thermal coefficient. Catalogue dn/dT values are relative to air, and SCHOTT also expresses the thermo-optical constant as G = α(n − 1) + dn/dT.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：玻璃的熱膨脹很小，所以溫度變化不會讓焦點移動。 正確的工程判斷必須回到機制與量級。","textEn":"Misconception: Glass expands so little that temperature changes cannot move the focus. Sound engineering judgement goes back to mechanism and magnitude.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"關於「熱離焦與光熱係數」，下列哪一項敘述正確？","questionEn":"Which statement about \"Thermal defocus and the opto-thermal coefficient\" is correct?","options":["玻璃的熱膨脹很小，所以溫度變化不會讓焦點移動。","空氣間隔雙合只是沒上膠的膠合透鏡，光學性能完全相同。","溫度同時改變折射率（dn/dT）與鏡片尺寸（膨脹係數 α），薄透鏡在空氣中的焦距變化率為 (1/f)·df/dT = α − (dn/dT)/(n − 1)，稱為光熱係數。"],"optionsEn":["Glass expands so little that temperature changes cannot move the focus.","An air-spaced doublet is just an uncemented cemented doublet with identical optics.","Temperature changes both the refractive index (dn/dT) and the lens dimensions (expansion coefficient α), and for a thin lens in air the focal-length change rate is (1/f)·df/dT = α − (dn/dT)/(n − 1), the opto-thermal coefficient."],"answer":2,"explanation":"溫度同時改變折射率（dn/dT）與鏡片尺寸（膨脹係數 α），薄透鏡在空氣中的焦距變化率為 (1/f)·df/dT = α − (dn/dT)/(n − 1)，稱為光熱係數。 其餘選項是常見誤解。","explanationEn":"Temperature changes both the refractive index (dn/dT) and the lens dimensions (expansion coefficient α), and for a thin lens in air the focal-length change rate is (1/f)·df/dT = α − (dn/dT)/(n − 1), the opto-thermal coefficient. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":17},{"id":"a405-v12-06","title":"熱離焦與光熱係數：定量估算","titleEn":"Thermal defocus and the opto-thermal coefficient: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-05"],"objective":"以數值模型估算「熱光係數與鏡筒膨脹」的關鍵量，並判斷參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Thermo-optic coefficient and barrel expansion” with a numerical model and judge the direction and size of changes when a parameter moves.","instruction":"依下列模型逐步重算：N-BK7：α = 7.1 ppm/K、相對 dn/dT = 3.0 ppm/K（e 線）、n_e − 1 = 0.5187，γ = 7.1 − 5.78 = 1.32 ppm/K；F2：8.2 − 4.4/0.6241 = 1.15 ppm/K。雙合權重 2.308 與 −1.308，γ = 2.308 × 1.32 − 1.308 × 1.15 ≈ 1.53 ppm/K。f = 100 mm、ΔT = 40 K：焦距伸長 6.1 µm；鋁鏡筒 100 mm × 23.6 ppm/K × 40 K = 94.4 µm，失配 88 µm，是 f/4 景深 ±2λN² = ±17.6 µm 的 5 倍；改用 Invar（1.2 ppm/K）隔圈伸長 4.8 µm，殘差僅 1.3 µm。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係。","instructionEn":"Recalculate step by step: N-BK7: α = 7.1 ppm/K, relative dn/dT = 3.0 ppm/K (e-line), n_e − 1 = 0.5187, so γ = 7.1 − 5.78 = 1.32 ppm/K; F2: 8.2 − 4.4/0.6241 = 1.15 ppm/K. With doublet weights 2.308 and −1.308, γ = 2.308 × 1.32 − 1.308 × 1.15 ≈ 1.53 ppm/K. For f = 100 mm and ΔT = 40 K the focal length grows 6.1 µm, while an aluminium barrel grows 100 mm × 23.6 ppm/K × 40 K = 94.4 µm, a mismatch of 88 µm, five times the f/4 depth of focus ±2λN² = ±17.6 µm; an Invar spacer (1.2 ppm/K) grows 4.8 µm, leaving only 1.3 µm. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, and state whether the dependence is linear, quadratic or steeper.","observation":"如何核對：把鏡頭與感測器裝在溫控箱中，於 −20、20、60 °C 各浸泡到熱平衡後量穿焦 MTF 求最佳焦距，算出 Δz/ΔT 與模型比較；另以千分錶或干涉測長單獨量鏡筒伸長，分離光學項與機構項；再做快速升溫測試，觀察徑向溫度梯度造成的暫態離焦與球差。","observationEn":"How to cross-check: Mount lens and sensor in a thermal chamber, soak to equilibrium at −20, 20 and 60 °C, measure through-focus MTF to find best focus and compare the resulting Δz/ΔT with the model; measure barrel growth separately with a dial gauge or interferometric length measurement to separate optical and mechanical terms; then run a fast ramp to observe transient defocus and spherical aberration from radial temperature gradients.","failure":"計算陷阱：單位換算錯誤、把教學假設當成設備規格，或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit conversion slips, treating teaching assumptions as equipment specifications, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與物理解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with a physical explanation.","knowledge":[{"id":"a405-v12-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"N-BK7：α = 7.1 ppm/K、相對 dn/dT = 3.0 ppm/K（e 線）、n_e − 1 = 0.5187，γ = 7.1 − 5.78 = 1.32 ppm/K；F2：8.2 − 4.4/0.6241 = 1.15 ppm/K。雙合權重 2.308 與 −1.308，γ = 2.308 × 1.32 − 1.308 × 1.15 ≈ 1.53 ppm/K。f = 100 mm、ΔT = 40 K：焦距伸長 6.1 µm；鋁鏡筒 100 mm × 23.6 ppm/K × 40 K = 94.4 µm，失配 88 µm，是 f/4 景深 ±2λN² = ±17.6 µm 的 5 倍；改用 Invar（1.2 ppm/K）隔圈伸長 4.8 µm，殘差僅 1.3 µm。","textEn":"N-BK7: α = 7.1 ppm/K, relative dn/dT = 3.0 ppm/K (e-line), n_e − 1 = 0.5187, so γ = 7.1 − 5.78 = 1.32 ppm/K; F2: 8.2 − 4.4/0.6241 = 1.15 ppm/K. With doublet weights 2.308 and −1.308, γ = 2.308 × 1.32 − 1.308 × 1.15 ≈ 1.53 ppm/K. For f = 100 mm and ΔT = 40 K the focal length grows 6.1 µm, while an aluminium barrel grows 100 mm × 23.6 ppm/K × 40 K = 94.4 µm, a mismatch of 88 µm, five times the f/4 depth of focus ±2λN² = ±17.6 µm; an Invar spacer (1.2 ppm/K) grows 4.8 µm, leaving only 1.3 µm.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設；套用到實際設備前，必須重新取得規格、操作條件與不確定度。","textEn":"These numbers are teaching assumptions; before applying them to real equipment, obtain the actual specifications, operating conditions and uncertainties.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"依「熱離焦與光熱係數」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Thermal defocus and the opto-thermal coefficient\", which statement holds?","options":["N-BK7：α = 7.1 ppm/K、相對 dn/dT = 3.0 ppm/K（e 線）、n_e − 1 = 0.5187，γ = 7.1 − 5.78 = 1.32 ppm/K。","只要鏡頭在綠光達到繞射極限，彩色影像就一定清晰。","只要鍍了抗反射膜，就不會出現鬼影。"],"optionsEn":["N-BK7: α = 7.1 ppm/K, relative dn/dT = 3.0 ppm/K (e-line), n_e − 1 = 0.5187, so γ = 7.1 − 5.78 = 1.32 ppm/K; F2: 8.2 − 4.4/0.6241 = 1.15 ppm/K.","If the lens is diffraction-limited in green, colour images will be sharp.","Once an antireflection coating is applied, ghosts cannot appear."],"answer":0,"explanation":"N-BK7：α = 7.1 ppm/K、相對 dn/dT = 3.0 ppm/K（e 線）、n_e − 1 = 0.5187，γ = 7.1 − 5.78 = 1.32 ppm/K；F2：8.2 − 4.4/0.6241 = 1.15 ppm/K。 重算時請保留單位。","explanationEn":"N-BK7: α = 7.1 ppm/K, relative dn/dT = 3.0 ppm/K (e-line), n_e − 1 = 0.5187, so γ = 7.1 − 5.78 = 1.32 ppm/K; F2: 8.2 − 4.4/0.6241 = 1.15 ppm/K. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":18},{"id":"a405-v12-07","title":"熱離焦與光熱係數：量測與驗證","titleEn":"Thermal defocus and the opto-thermal coefficient: measurement and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-06"],"objective":"設計一項可重複的量測，驗證「熱光係數與鏡筒膨脹」是否符合模型預期，並訂出允收準則。","objectiveEn":"Design a repeatable measurement that verifies whether “Thermo-optic coefficient and barrel expansion” meets the model expectation, and set acceptance criteria.","instruction":"把鏡頭與感測器裝在溫控箱中，於 −20、20、60 °C 各浸泡到熱平衡後量穿焦 MTF 求最佳焦距，算出 Δz/ΔT 與模型比較；另以千分錶或干涉測長單獨量鏡筒伸長，分離光學項與機構項；再做快速升溫測試，觀察徑向溫度梯度造成的暫態離焦與球差。 師傅任務：把上述方法寫成量測計畫，列出儀器、基準件或參考樣品、步驟、比較對象與允收準則，並估計三項主要不確定度來源。","instructionEn":"Mount lens and sensor in a thermal chamber, soak to equilibrium at −20, 20 and 60 °C, measure through-focus MTF to find best focus and compare the resulting Δz/ΔT with the model; measure barrel growth separately with a dial gauge or interferometric length measurement to separate optical and mechanical terms; then run a fast ramp to observe transient defocus and spherical aberration from radial temperature gradients. Mentor task: turn this into a measurement plan listing instruments, reference artefacts or samples, procedure, comparison baseline and acceptance criteria, and estimate the three largest uncertainty contributions.","observation":"注意干擾：鋁鏡筒在低溫收縮壓迫玻璃，產生應力雙折射與像散，嚴重時崩邊或破裂；黏著劑在高溫蠕變，鏡片位置不回復；溫度快速變化時徑向梯度造成暫態離焦，影像在數分鐘內忽清忽糊。","observationEn":"Watch for interference: An aluminium barrel shrinking at low temperature squeezes the glass, causing stress birefringence and astigmatism and in severe cases edge chipping or fracture; adhesive creeps at high temperature so the lens does not return to position; rapid temperature change creates radial gradients and transient defocus, so the image drifts in and out of focus for minutes.","failure":"驗證陷阱：只量一次、沒有可追溯的基準，或不記錄環境條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Verification traps: a single measurement, no traceable reference, or unrecorded environmental conditions make real deviations indistinguishable from measurement error.","check":"提交量測計畫：儀器、基準、步驟、允收準則與不確定度預算，並說明如何判定合格或不合格。","checkEn":"Submit the measurement plan: instruments, reference, procedure, acceptance criteria and uncertainty budget, with the pass/fail decision rule.","knowledge":[{"id":"a405-v12-07-k1","title":"驗證方法","titleEn":"Verification method","text":"把鏡頭與感測器裝在溫控箱中，於 −20、20、60 °C 各浸泡到熱平衡後量穿焦 MTF 求最佳焦距，算出 Δz/ΔT 與模型比較；另以千分錶或干涉測長單獨量鏡筒伸長，分離光學項與機構項；再做快速升溫測試，觀察徑向溫度梯度造成的暫態離焦與球差。","textEn":"Mount lens and sensor in a thermal chamber, soak to equilibrium at −20, 20 and 60 °C, measure through-focus MTF to find best focus and compare the resulting Δz/ΔT with the model; measure barrel growth separately with a dial gauge or interferometric length measurement to separate optical and mechanical terms; then run a fast ramp to observe transient defocus and spherical aberration from radial temperature gradients.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-07-k2","title":"允收與不確定度","titleEn":"Acceptance and uncertainty","text":"允收準則必須在量測前訂定，並與擴充不確定度一起陳述；比較基準需可追溯。","textEn":"Acceptance criteria are fixed before measuring and stated together with expanded uncertainty; the comparison reference must be traceable.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"要驗證「熱離焦與光熱係數」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Thermal defocus and the opto-thermal coefficient\"?","options":["沿用另一台設備或另一個案例的量測結果，就可視為本系統已完成驗證。","把鏡頭與感測器裝在溫控箱中，於 −20、20、60 °C 各浸泡到熱平衡後量穿焦 MTF 求最佳焦距，算出 Δz/ΔT 與模型比較。","量到的 MTF 只要比規格高一點點，就一定可以放行。"],"optionsEn":["Reusing results from another instrument or another case counts as verifying this system.","Mount lens and sensor in a thermal chamber, soak to equilibrium at −20, 20 and 60 °C, measure through-focus MTF to find best focus and compare the resulting Δz/ΔT with the model.","A lens whose measured MTF is just above spec can always be released."],"answer":1,"explanation":"把鏡頭與感測器裝在溫控箱中，於 −20、20、60 °C 各浸泡到熱平衡後量穿焦 MTF 求最佳焦距，算出 Δz/ΔT 與模型比較；另以千分錶或干涉測長單獨量鏡筒伸長，分離光學項與機構項；再做快速升溫測試，觀察徑向溫度梯度造成的暫態離焦與球差。 驗證需要基準、重複性與允收準則。","explanationEn":"Mount lens and sensor in a thermal chamber, soak to equilibrium at −20, 20 and 60 °C, measure through-focus MTF to find best focus and compare the resulting Δz/ΔT with the model; measure barrel growth separately with a dial gauge or interferometric length measurement to separate optical and mechanical terms; then run a fast ramp to observe transient defocus and spherical aberration from radial temperature gradients. Verification needs a reference, repeatability and acceptance criteria."},"unit":2,"unitFacet":"verification","order":7,"sequence":19},{"id":"a405-v12-08","title":"熱離焦與光熱係數：失效診斷","titleEn":"Thermal defocus and the opto-thermal coefficient: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-07"],"objective":"從症狀倒推「熱光係數與鏡筒膨脹」的失效原因，提出能區分原因的檢查與矯正措施。","objectiveEn":"Work back from symptoms to the failure causes of “Thermo-optic coefficient and barrel expansion” and propose discriminating checks and corrective actions.","instruction":"鋁鏡筒在低溫收縮壓迫玻璃，產生應力雙折射與像散，嚴重時崩邊或破裂；黏著劑在高溫蠕變，鏡片位置不回復；溫度快速變化時徑向梯度造成暫態離焦，影像在數分鐘內忽清忽糊。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測，以及矯正與預防措施；並說明此失效如何影響整個系統的性能、良率或安全。","instructionEn":"An aluminium barrel shrinking at low temperature squeezes the glass, causing stress birefringence and astigmatism and in severe cases edge chipping or fracture; adhesive creeps at high temperature so the lens does not return to position; rapid temperature change creates radial gradients and transient defocus, so the image drifts in and out of focus for minutes. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system performance, yield or safety.","observation":"連結機制：無熱化設計要讓像面移動與機構伸長相等，即 γ·f ≈ α_h·L，這對戶外相機、車載與太空光學尤其關鍵。","observationEn":"Link to the mechanism: Athermal design makes image-plane motion equal mount growth, γ·f ≈ α_h·L, which is critical for outdoor, automotive and space cameras.","failure":"誤判風險：若相信「玻璃的熱膨脹很小，所以溫度變化不會讓焦點移動。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Glass expands so little that temperature changes cannot move the focus.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，並指出哪一項量測能最快確認根因、如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement that confirms the root cause fastest, and state how recurrence is prevented.","knowledge":[{"id":"a405-v12-08-k1","title":"失效模式","titleEn":"Failure mode","text":"鋁鏡筒在低溫收縮壓迫玻璃，產生應力雙折射與像散，嚴重時崩邊或破裂；黏著劑在高溫蠕變，鏡片位置不回復；溫度快速變化時徑向梯度造成暫態離焦，影像在數分鐘內忽清忽糊。","textEn":"An aluminium barrel shrinking at low temperature squeezes the glass, causing stress birefringence and astigmatism and in severe cases edge chipping or fracture; adhesive creeps at high temperature so the lens does not return to position; rapid temperature change creates radial gradients and transient defocus, so the image drifts in and out of focus for minutes.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測確認；只更換零件或放寬參數可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement; merely swapping parts or relaxing limits can mask the problem.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"在「熱離焦與光熱係數」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Thermal defocus and the opto-thermal coefficient\" misbehaves, which diagnosis is most reasonable?","options":["調高增益或放寬允收值，就能解決大多數異常。","空氣間隔雙合只是沒上膠的膠合透鏡，光學性能完全相同。","鋁鏡筒在低溫收縮壓迫玻璃，產生應力雙折射與像散，嚴重時崩邊或破裂；黏著劑在高溫蠕變，鏡片位置不回復；溫度快速變化時徑向梯度造成暫態離焦，影像在數分鐘內忽清忽糊。"],"optionsEn":["Raising the gain or widening the acceptance limits solves most anomalies.","An air-spaced doublet is just an uncemented cemented doublet with identical optics.","An aluminium barrel shrinking at low temperature squeezes the glass, causing stress birefringence and astigmatism and in severe cases edge chipping or fracture."],"answer":2,"explanation":"鋁鏡筒在低溫收縮壓迫玻璃，產生應力雙折射與像散，嚴重時崩邊或破裂；黏著劑在高溫蠕變，鏡片位置不回復；溫度快速變化時徑向梯度造成暫態離焦，影像在數分鐘內忽清忽糊。 需以量測區分可能原因。","explanationEn":"An aluminium barrel shrinking at low temperature squeezes the glass, causing stress birefringence and astigmatism and in severe cases edge chipping or fracture; adhesive creeps at high temperature so the lens does not return to position; rapid temperature change creates radial gradients and transient defocus, so the image drifts in and out of focus for minutes. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":20}],"order":4},{"id":"a405-v12-s2","title":"元件、材料與製造","titleEn":"Components, materials and fabrication","description":"本階段聚焦「膠合與空氣間隔雙合透鏡的取捨」與「生產定心、磨邊與膠合工序」：先建立機制與定量模型，再設計驗證並診斷失效。","descriptionEn":"This stage covers \"Cemented versus air-spaced doublet trade-offs\" and \"Production centring, edging and cementing\": build the mechanism and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"a405-v12-09","title":"膠合與空氣間隔雙合透鏡的取捨：原理與系統邊界","titleEn":"Cemented versus air-spaced doublet trade-offs: mechanism and system boundary","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-08"],"objective":"說明「膠合界面與空氣間隔」如何決定消色差透鏡設計的關鍵性能，並畫出其輸入、輸出與邊界。","objectiveEn":"Explain how “Cemented interface and air gap” determines the key performance of “Achromatic lens design”, and map its inputs, outputs and boundaries.","instruction":"膠合雙合透鏡兩片內曲率相同，只有三個面，界面以折射率接近的膠填滿，反射極低、對位穩固、鬼影路徑少；但只有三個曲率，用來定光焦度、消色差與彎曲修正球差後就沒有自由度處理大孔徑下的色球差與彗差。膠層還要承受兩種玻璃膨脹係數差造成的剪應變，限制了口徑與玻璃組合，紫外與高功率雷射下膠也會吸收老化。空氣間隔版有四個曲率加一個間距，可在兩個波長同時修正球差並控制彗差，適合更快的 f 數與更大口徑，代價是間距與偏心公差、多兩個需鍍膜的空氣界面，以及間距誤差直接改變焦距。 師傅任務：以方塊圖畫出能量或訊號通過「膠合界面與空氣間隔」的路徑，標出哪些量由設計決定、哪些由環境或製造決定，再用三句話寫出機制摘要。","instructionEn":"A cemented doublet has equal inner radii and only three surfaces; the interface is filled with index-matched cement, so reflection is very low, alignment is robust and there are few ghost paths. But three curvatures are used up setting power, correcting colour and bending for spherical aberration, leaving no freedom for spherochromatism and coma at large aperture. The cement layer must also absorb the shear strain from the two glasses' expansion mismatch, which limits diameter and glass pairs, and cement absorbs and ages under UV and high-power lasers. An air-spaced version has four curvatures plus a gap, so it can correct spherical aberration at two wavelengths and control coma, suiting faster f-numbers and larger apertures, at the cost of spacing and decentre tolerances, two more air–glass surfaces to coat, and a gap error that changes focal length directly. Mentor task: draw a block diagram of the energy or signal path through “Cemented interface and air gap”, mark which quantities are fixed by design and which by environment or fabrication, then summarise the mechanism in three sentences.","observation":"量級提示：間距敏感度：φ = φ₁ + φ₂ − dφ₁φ₂，∂φ/∂d = −φ₁φ₂。","observationEn":"Order-of-magnitude cue: Gap sensitivity: φ = φ₁ + φ₂ − dφ₁φ₂, so ∂φ/∂d = −φ₁φ₂.","failure":"常見誤解：「空氣間隔雙合只是沒上膠的膠合透鏡，光學性能完全相同。」這個說法忽略了上述機制；請在方塊圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"An air-spaced doublet is just an uncemented cemented doublet with identical optics.\" It ignores the mechanism above; mark on your block diagram where it breaks down.","check":"方塊圖標明「膠合界面與空氣間隔」的輸入、輸出與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The block diagram shows inputs, outputs and boundaries of “Cemented interface and air gap”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"a405-v12-09-k1","title":"膠合與空氣間隔雙合透鏡的取捨","titleEn":"Cemented versus air-spaced doublet trade-offs","text":"膠合雙合透鏡兩片內曲率相同，只有三個面，界面以折射率接近的膠填滿，反射極低、對位穩固、鬼影路徑少；但只有三個曲率，用來定光焦度、消色差與彎曲修正球差後就沒有自由度處理大孔徑下的色球差與彗差。膠層還要承受兩種玻璃膨脹係數差造成的剪應變，限制了口徑與玻璃組合，紫外與高功率雷射下膠也會吸收老化。","textEn":"A cemented doublet has equal inner radii and only three surfaces; the interface is filled with index-matched cement, so reflection is very low, alignment is robust and there are few ghost paths. But three curvatures are used up setting power, correcting colour and bending for spherical aberration, leaving no freedom for spherochromatism and coma at large aperture.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：空氣間隔雙合只是沒上膠的膠合透鏡，光學性能完全相同。 正確的工程判斷必須回到機制與量級。","textEn":"Misconception: An air-spaced doublet is just an uncemented cemented doublet with identical optics. Sound engineering judgement goes back to mechanism and magnitude.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"關於「膠合與空氣間隔雙合透鏡的取捨」，下列哪一項敘述正確？","questionEn":"Which statement about \"Cemented versus air-spaced doublet trade-offs\" is correct?","options":["膠合雙合透鏡兩片內曲率相同，只有三個面，界面以折射率接近的膠填滿，反射極低、對位穩固、鬼影路徑少。","空氣間隔雙合只是沒上膠的膠合透鏡，光學性能完全相同。","鏡片拋光到正確曲率後自然就是同心的，不需要另外定心。"],"optionsEn":["A cemented doublet has equal inner radii and only three surfaces.","An air-spaced doublet is just an uncemented cemented doublet with identical optics.","A lens polished to the right radii is automatically centred."],"answer":0,"explanation":"膠合雙合透鏡兩片內曲率相同，只有三個面，界面以折射率接近的膠填滿，反射極低、對位穩固、鬼影路徑少；但只有三個曲率，用來定光焦度、消色差與彎曲修正球差後就沒有自由度處理大孔徑下的色球差與彗差。 其餘選項是常見誤解。","explanationEn":"A cemented doublet has equal inner radii and only three surfaces; the interface is filled with index-matched cement, so reflection is very low, alignment is robust and there are few ghost paths. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":21},{"id":"a405-v12-10","title":"膠合與空氣間隔雙合透鏡的取捨：定量估算","titleEn":"Cemented versus air-spaced doublet trade-offs: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-09"],"objective":"以數值模型估算「膠合界面與空氣間隔」的關鍵量，並判斷參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Cemented interface and air gap” with a numerical model and judge the direction and size of changes when a parameter moves.","instruction":"依下列模型逐步重算：間距敏感度：φ = φ₁ + φ₂ − dφ₁φ₂，∂φ/∂d = −φ₁φ₂。N-BK7/F2、f = 100 mm 時 f₁ = 43.3 mm、f₂ = −76.4 mm，−φ₁φ₂ = 3.02×10⁻⁴ mm⁻²，Δf = −f²·Δφ ≈ −3.02·Δd，隔圈差 10 µm 焦距就變 −30 µm。膠合界面反射：BK7/膠 (n = 1.56) 為 2.0×10⁻⁴、膠/F2 為 3.6×10⁻⁴，未鍍膜空氣界面約 4.3%。Ø50 mm 在 ΔT = 40 K 時邊緣錯位：BK7/F2（Δα = 1.1 ppm/K）1.1 µm，15 µm 膠層剪應變 0.07；CaF₂（18.9 ppm/K）配約 8 ppm/K 的火石 10.9 µm，剪應變 0.73。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係。","instructionEn":"Recalculate step by step: Gap sensitivity: φ = φ₁ + φ₂ − dφ₁φ₂, so ∂φ/∂d = −φ₁φ₂. For N-BK7/F2 at f = 100 mm, f₁ = 43.3 mm and f₂ = −76.4 mm give −φ₁φ₂ = 3.02×10⁻⁴ mm⁻² and Δf = −f²·Δφ ≈ −3.02·Δd, so a 10 µm spacer error moves focal length by −30 µm. Cement-interface reflectance: BK7 to cement (n = 1.56) 2.0×10⁻⁴ and cement to F2 3.6×10⁻⁴, against about 4.3% for an uncoated air surface. Edge mismatch for Ø50 mm over ΔT = 40 K: BK7/F2 (Δα = 1.1 ppm/K) 1.1 µm, a 0.07 shear strain in a 15 µm cement layer; CaF₂ (18.9 ppm/K) against a flint near 8 ppm/K gives 10.9 µm and 0.73. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, and state whether the dependence is linear, quadratic or steeper.","observation":"如何核對：空氣間隔版在組裝時以焦距量測台量有效焦距對隔圈厚度的變化，驗證 −3 µm/µm 的敏感度；以干涉儀或波前感測器在兩個波長量球差，確認色球差被修正；膠合版做 −40 到 +70 °C 熱循環，之後以斜射光檢查邊緣是否出現牛頓環或銀白脫膠，並以偏光儀檢查應力雙折射。","observationEn":"How to cross-check: For the air-spaced version measure effective focal length against spacer thickness on a focal-length bench during assembly to confirm the −3 µm/µm sensitivity, and measure spherical aberration at two wavelengths with an interferometer or wavefront sensor to confirm spherochromatism is corrected; cycle the cemented version from −40 to +70 °C, then inspect the edge under oblique light for Newton rings or silvery delamination and check stress birefringence with a polariscope.","failure":"計算陷阱：單位換算錯誤、把教學假設當成設備規格，或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit conversion slips, treating teaching assumptions as equipment specifications, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與物理解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with a physical explanation.","knowledge":[{"id":"a405-v12-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"間距敏感度：φ = φ₁ + φ₂ − dφ₁φ₂，∂φ/∂d = −φ₁φ₂。N-BK7/F2、f = 100 mm 時 f₁ = 43.3 mm、f₂ = −76.4 mm，−φ₁φ₂ = 3.02×10⁻⁴ mm⁻²，Δf = −f²·Δφ ≈ −3.02·Δd，隔圈差 10 µm 焦距就變 −30 µm。膠合界面反射：BK7/膠 (n = 1.56) 為 2.0×10⁻⁴、膠/F2 為 3.6×10⁻⁴，未鍍膜空氣界面約 4.3%。Ø50 mm 在 ΔT = 40 K 時邊緣錯位：BK7/F2（Δα = 1.1 ppm/K）1.1 µm，15 µm 膠層剪應變 0.07；CaF₂（18.9 ppm/K）配約 8 ppm/K 的火石 10.9 µm，剪應變 0.73。","textEn":"Gap sensitivity: φ = φ₁ + φ₂ − dφ₁φ₂, so ∂φ/∂d = −φ₁φ₂. For N-BK7/F2 at f = 100 mm, f₁ = 43.3 mm and f₂ = −76.4 mm give −φ₁φ₂ = 3.02×10⁻⁴ mm⁻² and Δf = −f²·Δφ ≈ −3.02·Δd, so a 10 µm spacer error moves focal length by −30 µm. Cement-interface reflectance: BK7 to cement (n = 1.56) 2.0×10⁻⁴ and cement to F2 3.6×10⁻⁴, against about 4.3% for an uncoated air surface. Edge mismatch for Ø50 mm over ΔT = 40 K: BK7/F2 (Δα = 1.1 ppm/K) 1.1 µm, a 0.07 shear strain in a 15 µm cement layer; CaF₂ (18.9 ppm/K) against a flint near 8 ppm/K gives 10.9 µm and 0.73.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設；套用到實際設備前，必須重新取得規格、操作條件與不確定度。","textEn":"These numbers are teaching assumptions; before applying them to real equipment, obtain the actual specifications, operating conditions and uncertainties.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"依「膠合與空氣間隔雙合透鏡的取捨」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Cemented versus air-spaced doublet trade-offs\", which statement holds?","options":["HeNe 干涉儀量到的波前合格，就代表整個可見光波段都合格。","間距敏感度：φ = φ₁ + φ₂ − dφ₁φ₂，∂φ/∂d = −φ₁φ₂。","量到的 MTF 只要比規格高一點點，就一定可以放行。"],"optionsEn":["A wavefront pass at 632.8 nm means the lens passes across the visible band.","Gap sensitivity: φ = φ₁ + φ₂ − dφ₁φ₂, so ∂φ/∂d = −φ₁φ₂.","A lens whose measured MTF is just above spec can always be released."],"answer":1,"explanation":"間距敏感度：φ = φ₁ + φ₂ − dφ₁φ₂，∂φ/∂d = −φ₁φ₂。 重算時請保留單位。","explanationEn":"Gap sensitivity: φ = φ₁ + φ₂ − dφ₁φ₂, so ∂φ/∂d = −φ₁φ₂. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":22},{"id":"a405-v12-11","title":"膠合與空氣間隔雙合透鏡的取捨：量測與驗證","titleEn":"Cemented versus air-spaced doublet trade-offs: measurement and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-10"],"objective":"設計一項可重複的量測，驗證「膠合界面與空氣間隔」是否符合模型預期，並訂出允收準則。","objectiveEn":"Design a repeatable measurement that verifies whether “Cemented interface and air gap” meets the model expectation, and set acceptance criteria.","instruction":"空氣間隔版在組裝時以焦距量測台量有效焦距對隔圈厚度的變化，驗證 −3 µm/µm 的敏感度；以干涉儀或波前感測器在兩個波長量球差，確認色球差被修正；膠合版做 −40 到 +70 °C 熱循環，之後以斜射光檢查邊緣是否出現牛頓環或銀白脫膠，並以偏光儀檢查應力雙折射。 師傅任務：把上述方法寫成量測計畫，列出儀器、基準件或參考樣品、步驟、比較對象與允收準則，並估計三項主要不確定度來源。","instructionEn":"For the air-spaced version measure effective focal length against spacer thickness on a focal-length bench during assembly to confirm the −3 µm/µm sensitivity, and measure spherical aberration at two wavelengths with an interferometer or wavefront sensor to confirm spherochromatism is corrected; cycle the cemented version from −40 to +70 °C, then inspect the edge under oblique light for Newton rings or silvery delamination and check stress birefringence with a polariscope. Mentor task: turn this into a measurement plan listing instruments, reference artefacts or samples, procedure, comparison baseline and acceptance criteria, and estimate the three largest uncertainty contributions.","observation":"注意干擾：膨脹係數差大的膠合組在低溫脫膠，邊緣出現牛頓環與銀白反光，波前與穿透率同時劣化；空氣間隔版的隔圈鬆動，受衝擊後間距與偏心改變，焦距與軸上彗差漂移；膠層在紫外光下黃化，藍端穿透率下降。","observationEn":"Watch for interference: A cemented pair with a large expansion mismatch delaminates in the cold, showing Newton rings and silvery reflections at the edge as wavefront and transmission degrade together; a loose spacer in an air-spaced doublet lets gap and decentre change after shock so focal length and on-axis coma drift; cement yellows under UV and blue transmission falls.","failure":"驗證陷阱：只量一次、沒有可追溯的基準，或不記錄環境條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Verification traps: a single measurement, no traceable reference, or unrecorded environmental conditions make real deviations indistinguishable from measurement error.","check":"提交量測計畫：儀器、基準、步驟、允收準則與不確定度預算，並說明如何判定合格或不合格。","checkEn":"Submit the measurement plan: instruments, reference, procedure, acceptance criteria and uncertainty budget, with the pass/fail decision rule.","knowledge":[{"id":"a405-v12-11-k1","title":"驗證方法","titleEn":"Verification method","text":"空氣間隔版在組裝時以焦距量測台量有效焦距對隔圈厚度的變化，驗證 −3 µm/µm 的敏感度；以干涉儀或波前感測器在兩個波長量球差，確認色球差被修正；膠合版做 −40 到 +70 °C 熱循環，之後以斜射光檢查邊緣是否出現牛頓環或銀白脫膠，並以偏光儀檢查應力雙折射。","textEn":"For the air-spaced version measure effective focal length against spacer thickness on a focal-length bench during assembly to confirm the −3 µm/µm sensitivity, and measure spherical aberration at two wavelengths with an interferometer or wavefront sensor to confirm spherochromatism is corrected; cycle the cemented version from −40 to +70 °C, then inspect the edge under oblique light for Newton rings or silvery delamination and check stress birefringence with a polariscope.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-11-k2","title":"允收與不確定度","titleEn":"Acceptance and uncertainty","text":"允收準則必須在量測前訂定，並與擴充不確定度一起陳述；比較基準需可追溯。","textEn":"Acceptance criteria are fixed before measuring and stated together with expanded uncertainty; the comparison reference must be traceable.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"要驗證「膠合與空氣間隔雙合透鏡的取捨」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Cemented versus air-spaced doublet trade-offs\"?","options":["只看單次讀值或外觀即可判定合格，不需要基準件或重複量測。","只要兩片玻璃的阿貝數差夠大，就能完全消除二級光譜。","空氣間隔版在組裝時以焦距量測台量有效焦距對隔圈厚度的變化，驗證 −3 µm/µm 的敏感度。"],"optionsEn":["A single reading or a visual impression is enough to accept the result; no reference artefact or repeat measurement is needed.","A large enough Abbe-number difference between two glasses eliminates the secondary spectrum.","For the air-spaced version measure effective focal length against spacer thickness on a focal-length bench during assembly to confirm the −3 µm/µm sensitivity, and measure spherical aberration at two wavelengths with an interferometer or wavefront sensor to confirm spherochromatism is corrected."],"answer":2,"explanation":"空氣間隔版在組裝時以焦距量測台量有效焦距對隔圈厚度的變化，驗證 −3 µm/µm 的敏感度；以干涉儀或波前感測器在兩個波長量球差，確認色球差被修正；膠合版做 −40 到 +70 °C 熱循環，之後以斜射光檢查邊緣是否出現牛頓環或銀白脫膠，並以偏光儀檢查應力雙折射。 驗證需要基準、重複性與允收準則。","explanationEn":"For the air-spaced version measure effective focal length against spacer thickness on a focal-length bench during assembly to confirm the −3 µm/µm sensitivity, and measure spherical aberration at two wavelengths with an interferometer or wavefront sensor to confirm spherochromatism is corrected; cycle the cemented version from −40 to +70 °C, then inspect the edge under oblique light for Newton rings or silvery delamination and check stress birefringence with a polariscope. Verification needs a reference, repeatability and acceptance criteria."},"unit":3,"unitFacet":"verification","order":3,"sequence":23},{"id":"a405-v12-12","title":"膠合與空氣間隔雙合透鏡的取捨：失效診斷","titleEn":"Cemented versus air-spaced doublet trade-offs: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-11"],"objective":"從症狀倒推「膠合界面與空氣間隔」的失效原因，提出能區分原因的檢查與矯正措施。","objectiveEn":"Work back from symptoms to the failure causes of “Cemented interface and air gap” and propose discriminating checks and corrective actions.","instruction":"膨脹係數差大的膠合組在低溫脫膠，邊緣出現牛頓環與銀白反光，波前與穿透率同時劣化；空氣間隔版的隔圈鬆動，受衝擊後間距與偏心改變，焦距與軸上彗差漂移；膠層在紫外光下黃化，藍端穿透率下降。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測，以及矯正與預防措施；並說明此失效如何影響整個系統的性能、良率或安全。","instructionEn":"A cemented pair with a large expansion mismatch delaminates in the cold, showing Newton rings and silvery reflections at the edge as wavefront and transmission degrade together; a loose spacer in an air-spaced doublet lets gap and decentre change after shock so focal length and on-axis coma drift; cement yellows under UV and blue transmission falls. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system performance, yield or safety.","observation":"連結機制：空氣間隔版有四個曲率加一個間距，可在兩個波長同時修正球差並控制彗差，適合更快的 f 數與更大口徑，代價是間距與偏心公差、多兩個需鍍膜的空氣界面，以及間距誤差直接改變焦距。","observationEn":"Link to the mechanism: An air-spaced version has four curvatures plus a gap, so it can correct spherical aberration at two wavelengths and control coma, suiting faster f-numbers and larger apertures, at the cost of spacing and decentre tolerances, two more air–glass surfaces to coat, and a gap error that changes focal length directly.","failure":"誤判風險：若相信「空氣間隔雙合只是沒上膠的膠合透鏡，光學性能完全相同。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"An air-spaced doublet is just an uncemented cemented doublet with identical optics.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，並指出哪一項量測能最快確認根因、如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement that confirms the root cause fastest, and state how recurrence is prevented.","knowledge":[{"id":"a405-v12-12-k1","title":"失效模式","titleEn":"Failure mode","text":"膨脹係數差大的膠合組在低溫脫膠，邊緣出現牛頓環與銀白反光，波前與穿透率同時劣化；空氣間隔版的隔圈鬆動，受衝擊後間距與偏心改變，焦距與軸上彗差漂移；膠層在紫外光下黃化，藍端穿透率下降。","textEn":"A cemented pair with a large expansion mismatch delaminates in the cold, showing Newton rings and silvery reflections at the edge as wavefront and transmission degrade together; a loose spacer in an air-spaced doublet lets gap and decentre change after shock so focal length and on-axis coma drift; cement yellows under UV and blue transmission falls.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測確認；只更換零件或放寬參數可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement; merely swapping parts or relaxing limits can mask the problem.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"在「膠合與空氣間隔雙合透鏡的取捨」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Cemented versus air-spaced doublet trade-offs\" misbehaves, which diagnosis is most reasonable?","options":["膨脹係數差大的膠合組在低溫脫膠，邊緣出現牛頓環與銀白反光，波前與穿透率同時劣化。","異常只出現一次就可以忽略，不需要記錄或追蹤。","鏡片拋光到正確曲率後自然就是同心的，不需要另外定心。"],"optionsEn":["A cemented pair with a large expansion mismatch delaminates in the cold, showing Newton rings and silvery reflections at the edge as wavefront and transmission degrade together.","An anomaly that appears only once can be ignored without logging or follow-up.","A lens polished to the right radii is automatically centred."],"answer":0,"explanation":"膨脹係數差大的膠合組在低溫脫膠，邊緣出現牛頓環與銀白反光，波前與穿透率同時劣化；空氣間隔版的隔圈鬆動，受衝擊後間距與偏心改變，焦距與軸上彗差漂移；膠層在紫外光下黃化，藍端穿透率下降。 需以量測區分可能原因。","explanationEn":"A cemented pair with a large expansion mismatch delaminates in the cold, showing Newton rings and silvery reflections at the edge as wavefront and transmission degrade together; a loose spacer in an air-spaced doublet lets gap and decentre change after shock so focal length and on-axis coma drift; cement yellows under UV and blue transmission falls. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":24},{"id":"a405-v12-13","title":"生產定心、磨邊與膠合工序：原理與系統邊界","titleEn":"Production centring, edging and cementing: mechanism and system boundary","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-12"],"objective":"說明「定心磨邊與膠合治具」如何決定消色差透鏡設計的關鍵性能，並畫出其輸入、輸出與邊界。","objectiveEn":"Explain how “Centring, edging and cementing fixtures” determines the key performance of “Achromatic lens design”, and map its inputs, outputs and boundaries.","instruction":"拋光完成的鏡片，其光軸（兩曲率中心的連線）通常不與外徑同軸。定心磨邊時把鏡片裝在主軸上，先讓光軸對準旋轉軸：曲率夠大的鏡片可用鐘形夾頭自動定心，曲率淺的彎月或弱負透鏡夾持角不足，必須以自準直儀觀察反射像隨旋轉的晃動做光學定心，再把外徑磨成與光軸同心，殘差以楔角或邊厚差表示。膠合時兩片在 10 到 20 µm 的膠層上相對移動，同時觀察各面反射像使它們同心，再以紫外或加熱固化；膠的固化收縮會拉動鏡片，所以固化後必須再量一次整組的定心。 師傅任務：以方塊圖畫出能量或訊號通過「定心磨邊與膠合治具」的路徑，標出哪些量由設計決定、哪些由環境或製造決定，再用三句話寫出機制摘要。","instructionEn":"A polished element's optical axis, the line through its two centres of curvature, generally does not coincide with its outer diameter. In centring and edging the element sits on a spindle and its optical axis is first aligned to the rotation axis: strongly curved elements self-centre in bell chucks, while shallow menisci and weak negative lenses lack clamping angle and must be centred optically by watching the reflected image wobble in an autocollimator; the edge is then ground concentric with the optical axis, and the residual is stated as wedge or edge-thickness variation. In cementing the two elements are slid on a 10 to 20 µm cement layer while the reflected images of all surfaces are made concentric, then cured by UV or heat; cure shrinkage pulls the elements, so the centring of the finished pair must be measured again after cure. Mentor task: draw a block diagram of the energy or signal path through “Centring, edging and cementing fixtures”, mark which quantities are fixed by design and which by environment or fabrication, then summarise the mechanism in three sentences.","observation":"量級提示：半徑 R = 60 mm 的面偏心 c = 10 µm，傾斜 ε = c/R = 0.167 mrad（0.57′）；Ø25 mm 的邊厚差 25 mm × 0.167 mrad = 4.2 µm；光束偏折 (n − 1)ε = 0.517 × 0.167 mrad = 86 µrad = 17.8″，在 f = 100 mm 像面造成 8.6 µm 的視軸偏移，約 2.5 個 3.45 µm 像素。","observationEn":"Order-of-magnitude cue: A surface of radius R = 60 mm decentred by c = 10 µm tilts by ε = c/R = 0.167 mrad (0.57′); over Ø25 mm the edge-thickness variation is 25 mm × 0.167 mrad = 4.2 µm; the beam deviates by (n − 1)ε = 0.517 × 0.167 mrad = 86 µrad = 17.8″, shifting the boresight by 8.6 µm at f = 100 mm, about 2.5 pixels of 3.45 µm.","failure":"常見誤解：「鏡片拋光到正確曲率後自然就是同心的，不需要另外定心。」這個說法忽略了上述機制；請在方塊圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A lens polished to the right radii is automatically centred.\" It ignores the mechanism above; mark on your block diagram where it breaks down.","check":"方塊圖標明「定心磨邊與膠合治具」的輸入、輸出與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The block diagram shows inputs, outputs and boundaries of “Centring, edging and cementing fixtures”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"a405-v12-13-k1","title":"生產定心、磨邊與膠合工序","titleEn":"Production centring, edging and cementing","text":"拋光完成的鏡片，其光軸（兩曲率中心的連線）通常不與外徑同軸。定心磨邊時把鏡片裝在主軸上，先讓光軸對準旋轉軸：曲率夠大的鏡片可用鐘形夾頭自動定心，曲率淺的彎月或弱負透鏡夾持角不足，必須以自準直儀觀察反射像隨旋轉的晃動做光學定心，再把外徑磨成與光軸同心，殘差以楔角或邊厚差表示。","textEn":"A polished element's optical axis, the line through its two centres of curvature, generally does not coincide with its outer diameter. In centring and edging the element sits on a spindle and its optical axis is first aligned to the rotation axis: strongly curved elements self-centre in bell chucks, while shallow menisci and weak negative lenses lack clamping angle and must be centred optically by watching the reflected image wobble in an autocollimator; the edge is then ground concentric with the optical axis, and the residual is stated as wedge or edge-thickness variation.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：鏡片拋光到正確曲率後自然就是同心的，不需要另外定心。 正確的工程判斷必須回到機制與量級。","textEn":"Misconception: A lens polished to the right radii is automatically centred. Sound engineering judgement goes back to mechanism and magnitude.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"關於「生產定心、磨邊與膠合工序」，下列哪一項敘述正確？","questionEn":"Which statement about \"Production centring, edging and cementing\" is correct?","options":["鏡片拋光到正確曲率後自然就是同心的，不需要另外定心。","拋光完成的鏡片，其光軸（兩曲率中心的連線）通常不與外徑同軸。","只要鏡頭在綠光達到繞射極限，彩色影像就一定清晰。"],"optionsEn":["A lens polished to the right radii is automatically centred.","A polished element's optical axis, the line through its two centres of curvature, generally does not coincide with its outer diameter.","If the lens is diffraction-limited in green, colour images will be sharp."],"answer":1,"explanation":"拋光完成的鏡片，其光軸（兩曲率中心的連線）通常不與外徑同軸。 其餘選項是常見誤解。","explanationEn":"A polished element's optical axis, the line through its two centres of curvature, generally does not coincide with its outer diameter. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":25},{"id":"a405-v12-14","title":"生產定心、磨邊與膠合工序：定量估算","titleEn":"Production centring, edging and cementing: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-13"],"objective":"以數值模型估算「定心磨邊與膠合治具」的關鍵量，並判斷參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Centring, edging and cementing fixtures” with a numerical model and judge the direction and size of changes when a parameter moves.","instruction":"依下列模型逐步重算：半徑 R = 60 mm 的面偏心 c = 10 µm，傾斜 ε = c/R = 0.167 mrad（0.57′）；Ø25 mm 的邊厚差 25 mm × 0.167 mrad = 4.2 µm；光束偏折 (n − 1)ε = 0.517 × 0.167 mrad = 86 µrad = 17.8″，在 f = 100 mm 像面造成 8.6 µm 的視軸偏移，約 2.5 個 3.45 µm 像素。曲率中心自準直時，偏心 c 在主軸旋轉下表現為半徑 2c = 20 µm 的圓。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係。","instructionEn":"Recalculate step by step: A surface of radius R = 60 mm decentred by c = 10 µm tilts by ε = c/R = 0.167 mrad (0.57′); over Ø25 mm the edge-thickness variation is 25 mm × 0.167 mrad = 4.2 µm; the beam deviates by (n − 1)ε = 0.517 × 0.167 mrad = 86 µrad = 17.8″, shifting the boresight by 8.6 µm at f = 100 mm, about 2.5 pixels of 3.45 µm. In centre-of-curvature autocollimation the decentre c appears as a circle of radius 2c = 20 µm as the spindle turns. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, and state whether the dependence is linear, quadratic or steeper.","observation":"如何核對：單片以迴轉台與千分錶量邊厚差，或以定心儀量各面曲率中心相對基準軸的偏移；膠合固化後用多面定心量測儀透過所有面量整組偏心，並以平行光管比較光學視軸與機械軸；把每片的偏心、邊厚差與固化前後差值記錄到序號。","observationEn":"How to cross-check: Measure each element's edge-thickness variation with a rotary table and dial gauge, or the offset of each surface's centre of curvature from the datum axis with a centring instrument; after cure measure the pair's decentration through all surfaces with a multi-surface centring instrument and compare optical boresight with the mechanical axis using a collimator; log each element's decentre, edge variation and pre- and post-cure difference against its serial number.","failure":"計算陷阱：單位換算錯誤、把教學假設當成設備規格，或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit conversion slips, treating teaching assumptions as equipment specifications, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與物理解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with a physical explanation.","knowledge":[{"id":"a405-v12-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"半徑 R = 60 mm 的面偏心 c = 10 µm，傾斜 ε = c/R = 0.167 mrad（0.57′）；Ø25 mm 的邊厚差 25 mm × 0.167 mrad = 4.2 µm；光束偏折 (n − 1)ε = 0.517 × 0.167 mrad = 86 µrad = 17.8″，在 f = 100 mm 像面造成 8.6 µm 的視軸偏移，約 2.5 個 3.45 µm 像素。曲率中心自準直時，偏心 c 在主軸旋轉下表現為半徑 2c = 20 µm 的圓。","textEn":"A surface of radius R = 60 mm decentred by c = 10 µm tilts by ε = c/R = 0.167 mrad (0.57′); over Ø25 mm the edge-thickness variation is 25 mm × 0.167 mrad = 4.2 µm; the beam deviates by (n − 1)ε = 0.517 × 0.167 mrad = 86 µrad = 17.8″, shifting the boresight by 8.6 µm at f = 100 mm, about 2.5 pixels of 3.45 µm. In centre-of-curvature autocollimation the decentre c appears as a circle of radius 2c = 20 µm as the spindle turns.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設；套用到實際設備前，必須重新取得規格、操作條件與不確定度。","textEn":"These numbers are teaching assumptions; before applying them to real equipment, obtain the actual specifications, operating conditions and uncertainties.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"依「生產定心、磨邊與膠合工序」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Production centring, edging and cementing\", which statement holds?","options":["只要鍍了抗反射膜，就不會出現鬼影。","只要兩片玻璃的阿貝數差夠大，就能完全消除二級光譜。","半徑 R = 60 mm 的面偏心 c = 10 µm，傾斜 ε = c/R = 0.167 mrad（0.57′）。"],"optionsEn":["Once an antireflection coating is applied, ghosts cannot appear.","A large enough Abbe-number difference between two glasses eliminates the secondary spectrum.","A surface of radius R = 60 mm decentred by c = 10 µm tilts by ε = c/R = 0.167 mrad (0.57′)."],"answer":2,"explanation":"半徑 R = 60 mm 的面偏心 c = 10 µm，傾斜 ε = c/R = 0.167 mrad（0.57′）；Ø25 mm 的邊厚差 25 mm × 0.167 mrad = 4.2 µm；光束偏折 (n − 1)ε = 0.517 × 0.167 mrad = 86 µrad = 17.8″，在 f = 100 mm 像面造成 8.6 µm 的視軸偏移，約 2.5 個 3.45 µm 像素。 重算時請保留單位。","explanationEn":"A surface of radius R = 60 mm decentred by c = 10 µm tilts by ε = c/R = 0.167 mrad (0.57′); over Ø25 mm the edge-thickness variation is 25 mm × 0.167 mrad = 4.2 µm; the beam deviates by (n − 1)ε = 0.517 × 0.167 mrad = 86 µrad = 17.8″, shifting the boresight by 8.6 µm at f = 100 mm, about 2.5 pixels of 3.45 µm. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":26},{"id":"a405-v12-15","title":"生產定心、磨邊與膠合工序：量測與驗證","titleEn":"Production centring, edging and cementing: measurement and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-14"],"objective":"設計一項可重複的量測，驗證「定心磨邊與膠合治具」是否符合模型預期，並訂出允收準則。","objectiveEn":"Design a repeatable measurement that verifies whether “Centring, edging and cementing fixtures” meets the model expectation, and set acceptance criteria.","instruction":"單片以迴轉台與千分錶量邊厚差，或以定心儀量各面曲率中心相對基準軸的偏移；膠合固化後用多面定心量測儀透過所有面量整組偏心，並以平行光管比較光學視軸與機械軸；把每片的偏心、邊厚差與固化前後差值記錄到序號。 師傅任務：把上述方法寫成量測計畫，列出儀器、基準件或參考樣品、步驟、比較對象與允收準則，並估計三項主要不確定度來源。","instructionEn":"Measure each element's edge-thickness variation with a rotary table and dial gauge, or the offset of each surface's centre of curvature from the datum axis with a centring instrument; after cure measure the pair's decentration through all surfaces with a multi-surface centring instrument and compare optical boresight with the mechanical axis using a collimator; log each element's decentre, edge variation and pre- and post-cure difference against its serial number. Mentor task: turn this into a measurement plan listing instruments, reference artefacts or samples, procedure, comparison baseline and acceptance criteria, and estimate the three largest uncertainty contributions.","observation":"注意干擾：膠層厚度不均使固化收縮不對稱，濕膠時對準良好的組件固化後出現楔角；膠中氣泡或灰塵成為散射點；磨邊崩角成為應力集中處，熱循環時裂紋由此擴展；邊厚差超規使軸上出現彗差，影像清晰度在視場兩側不對稱。","observationEn":"Watch for interference: Uneven cement thickness makes cure shrinkage asymmetric, so a pair aligned perfectly while wet acquires a wedge after cure; bubbles or dust in the cement become scatter points; edge chips from edging concentrate stress and cracks grow from them during thermal cycling; out-of-spec edge variation puts coma on axis and makes sharpness asymmetric across the field.","failure":"驗證陷阱：只量一次、沒有可追溯的基準，或不記錄環境條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Verification traps: a single measurement, no traceable reference, or unrecorded environmental conditions make real deviations indistinguishable from measurement error.","check":"提交量測計畫：儀器、基準、步驟、允收準則與不確定度預算，並說明如何判定合格或不合格。","checkEn":"Submit the measurement plan: instruments, reference, procedure, acceptance criteria and uncertainty budget, with the pass/fail decision rule.","knowledge":[{"id":"a405-v12-15-k1","title":"驗證方法","titleEn":"Verification method","text":"單片以迴轉台與千分錶量邊厚差，或以定心儀量各面曲率中心相對基準軸的偏移；膠合固化後用多面定心量測儀透過所有面量整組偏心，並以平行光管比較光學視軸與機械軸；把每片的偏心、邊厚差與固化前後差值記錄到序號。","textEn":"Measure each element's edge-thickness variation with a rotary table and dial gauge, or the offset of each surface's centre of curvature from the datum axis with a centring instrument; after cure measure the pair's decentration through all surfaces with a multi-surface centring instrument and compare optical boresight with the mechanical axis using a collimator; log each element's decentre, edge variation and pre- and post-cure difference against its serial number.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-15-k2","title":"允收與不確定度","titleEn":"Acceptance and uncertainty","text":"允收準則必須在量測前訂定，並與擴充不確定度一起陳述；比較基準需可追溯。","textEn":"Acceptance criteria are fixed before measuring and stated together with expanded uncertainty; the comparison reference must be traceable.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"要驗證「生產定心、磨邊與膠合工序」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Production centring, edging and cementing\"?","options":["單片以迴轉台與千分錶量邊厚差，或以定心儀量各面曲率中心相對基準軸的偏移。","不確定度太難估計，報告中只寫最佳值即可。","玻璃的熱膨脹很小，所以溫度變化不會讓焦點移動。"],"optionsEn":["Measure each element's edge-thickness variation with a rotary table and dial gauge, or the offset of each surface's centre of curvature from the datum axis with a centring instrument.","Uncertainty is too hard to estimate, so the report may state only the best value.","Glass expands so little that temperature changes cannot move the focus."],"answer":0,"explanation":"單片以迴轉台與千分錶量邊厚差，或以定心儀量各面曲率中心相對基準軸的偏移；膠合固化後用多面定心量測儀透過所有面量整組偏心，並以平行光管比較光學視軸與機械軸；把每片的偏心、邊厚差與固化前後差值記錄到序號。 驗證需要基準、重複性與允收準則。","explanationEn":"Measure each element's edge-thickness variation with a rotary table and dial gauge, or the offset of each surface's centre of curvature from the datum axis with a centring instrument; after cure measure the pair's decentration through all surfaces with a multi-surface centring instrument and compare optical boresight with the mechanical axis using a collimator; log each element's decentre, edge variation and pre- and post-cure difference against its serial number. Verification needs a reference, repeatability and acceptance criteria."},"unit":4,"unitFacet":"verification","order":7,"sequence":27},{"id":"a405-v12-16","title":"生產定心、磨邊與膠合工序：失效診斷","titleEn":"Production centring, edging and cementing: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-15"],"objective":"從症狀倒推「定心磨邊與膠合治具」的失效原因，提出能區分原因的檢查與矯正措施。","objectiveEn":"Work back from symptoms to the failure causes of “Centring, edging and cementing fixtures” and propose discriminating checks and corrective actions.","instruction":"膠層厚度不均使固化收縮不對稱，濕膠時對準良好的組件固化後出現楔角；膠中氣泡或灰塵成為散射點；磨邊崩角成為應力集中處，熱循環時裂紋由此擴展；邊厚差超規使軸上出現彗差，影像清晰度在視場兩側不對稱。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測，以及矯正與預防措施；並說明此失效如何影響整個系統的性能、良率或安全。","instructionEn":"Uneven cement thickness makes cure shrinkage asymmetric, so a pair aligned perfectly while wet acquires a wedge after cure; bubbles or dust in the cement become scatter points; edge chips from edging concentrate stress and cracks grow from them during thermal cycling; out-of-spec edge variation puts coma on axis and makes sharpness asymmetric across the field. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system performance, yield or safety.","observation":"連結機制：膠合時兩片在 10 到 20 µm 的膠層上相對移動，同時觀察各面反射像使它們同心，再以紫外或加熱固化；膠的固化收縮會拉動鏡片，所以固化後必須再量一次整組的定心。","observationEn":"Link to the mechanism: In cementing the two elements are slid on a 10 to 20 µm cement layer while the reflected images of all surfaces are made concentric, then cured by UV or heat; cure shrinkage pulls the elements, so the centring of the finished pair must be measured again after cure.","failure":"誤判風險：若相信「鏡片拋光到正確曲率後自然就是同心的，不需要另外定心。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A lens polished to the right radii is automatically centred.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，並指出哪一項量測能最快確認根因、如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement that confirms the root cause fastest, and state how recurrence is prevented.","knowledge":[{"id":"a405-v12-16-k1","title":"失效模式","titleEn":"Failure mode","text":"膠層厚度不均使固化收縮不對稱，濕膠時對準良好的組件固化後出現楔角；膠中氣泡或灰塵成為散射點；磨邊崩角成為應力集中處，熱循環時裂紋由此擴展；邊厚差超規使軸上出現彗差，影像清晰度在視場兩側不對稱。","textEn":"Uneven cement thickness makes cure shrinkage asymmetric, so a pair aligned perfectly while wet acquires a wedge after cure; bubbles or dust in the cement become scatter points; edge chips from edging concentrate stress and cracks grow from them during thermal cycling; out-of-spec edge variation puts coma on axis and makes sharpness asymmetric across the field.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測確認；只更換零件或放寬參數可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement; merely swapping parts or relaxing limits can mask the problem.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"在「生產定心、磨邊與膠合工序」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Production centring, edging and cementing\" misbehaves, which diagnosis is most reasonable?","options":["先更換最貴的零件；只要症狀消失，就代表已找到根因。","膠層厚度不均使固化收縮不對稱，濕膠時對準良好的組件固化後出現楔角。","只要鏡頭在綠光達到繞射極限，彩色影像就一定清晰。"],"optionsEn":["Replace the most expensive part first; if the symptom disappears, the root cause has been found.","Uneven cement thickness makes cure shrinkage asymmetric, so a pair aligned perfectly while wet acquires a wedge after cure.","If the lens is diffraction-limited in green, colour images will be sharp."],"answer":1,"explanation":"膠層厚度不均使固化收縮不對稱，濕膠時對準良好的組件固化後出現楔角；膠中氣泡或灰塵成為散射點；磨邊崩角成為應力集中處，熱循環時裂紋由此擴展；邊厚差超規使軸上出現彗差，影像清晰度在視場兩側不對稱。 需以量測區分可能原因。","explanationEn":"Uneven cement thickness makes cure shrinkage asymmetric, so a pair aligned perfectly while wet acquires a wedge after cure; bubbles or dust in the cement become scatter points; edge chips from edging concentrate stress and cracks grow from them during thermal cycling; out-of-spec edge variation puts coma on axis and makes sharpness asymmetric across the field. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":28}],"order":5},{"id":"a405-v12-s3","title":"量測、校正與誤差預算","titleEn":"Measurement, calibration and error budgets","description":"本階段聚焦「依感測器匹配設計與 MTF 判準」與「干涉儀穿透波前量測與波長換算」：先建立機制與定量模型，再設計驗證並診斷失效。","descriptionEn":"This stage covers \"Sensor-matched design and MTF criteria\" and \"Interferometric transmitted-wavefront test and wavelength conversion\": build the mechanism and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"a405-v12-17","title":"依感測器匹配設計與 MTF 判準：原理與系統邊界","titleEn":"Sensor-matched design and MTF criteria: mechanism and system boundary","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-16"],"objective":"說明「感測器像素與 MTF」如何決定消色差透鏡設計的關鍵性能，並畫出其輸入、輸出與邊界。","objectiveEn":"Explain how “Sensor pixels and MTF” determines the key performance of “Achromatic lens design”, and map its inputs, outputs and boundaries.","instruction":"相機用的消色差透鏡要以感測器取樣來評判：像素間距 p 決定 Nyquist 頻率 ν_N = 1/(2p)，系統 MTF 等於鏡頭 MTF 乘像素孔徑的 sinc 響應；鏡頭在 f 數 N 的繞射截止頻率為 1/(λN)。殘餘的二級光譜就是隨波長變化的離焦，多色 MTF 要以感測器光譜響應加權；拜耳濾色片讓紅藍通道的取樣頻率再減半。因此規格應寫成在 Nyquist 或其一半、中心與邊緣的多色 MTF，並要求各色焦點散佈落在 ±2λN² 的像素尺度景深內。 師傅任務：以方塊圖畫出能量或訊號通過「感測器像素與 MTF」的路徑，標出哪些量由設計決定、哪些由環境或製造決定，再用三句話寫出機制摘要。","instructionEn":"An achromat for a camera must be judged against sensor sampling: pixel pitch p sets the Nyquist frequency ν_N = 1/(2p), and system MTF is lens MTF times the sinc response of the pixel aperture, with the lens's diffraction cutoff at 1/(λN) for f-number N. Residual secondary spectrum is a wavelength-dependent defocus, so polychromatic MTF must be weighted by the sensor's spectral response, and a Bayer filter halves the sampling rate again for the red and blue channels. The specification should therefore state polychromatic MTF at Nyquist or half Nyquist at centre and edge, and require the colour focus spread to fall within the pixel-scale depth of focus ±2λN². Mentor task: draw a block diagram of the energy or signal path through “Sensor pixels and MTF”, mark which quantities are fixed by design and which by environment or fabrication, then summarise the mechanism in three sentences.","observation":"量級提示：p = 3.45 µm，ν_N = 145 lp/mm；f/4、0.55 µm 截止 455 lp/mm，繞射 MTF(145) ≈ 0.60，像素 sinc 0.64，未計像差已只剩 0.38。","observationEn":"Order-of-magnitude cue: p = 3.45 µm gives ν_N = 145 lp/mm; at f/4 and 0.55 µm the cutoff is 455 lp/mm, diffraction MTF(145) ≈ 0.60 and pixel sinc 0.64, already 0.38 before aberrations.","failure":"常見誤解：「只要鏡頭在綠光達到繞射極限，彩色影像就一定清晰。」這個說法忽略了上述機制；請在方塊圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"If the lens is diffraction-limited in green, colour images will be sharp.\" It ignores the mechanism above; mark on your block diagram where it breaks down.","check":"方塊圖標明「感測器像素與 MTF」的輸入、輸出與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The block diagram shows inputs, outputs and boundaries of “Sensor pixels and MTF”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"a405-v12-17-k1","title":"依感測器匹配設計與 MTF 判準","titleEn":"Sensor-matched design and MTF criteria","text":"相機用的消色差透鏡要以感測器取樣來評判：像素間距 p 決定 Nyquist 頻率 ν_N = 1/(2p)，系統 MTF 等於鏡頭 MTF 乘像素孔徑的 sinc 響應；鏡頭在 f 數 N 的繞射截止頻率為 1/(λN)。殘餘的二級光譜就是隨波長變化的離焦，多色 MTF 要以感測器光譜響應加權；拜耳濾色片讓紅藍通道的取樣頻率再減半。","textEn":"An achromat for a camera must be judged against sensor sampling: pixel pitch p sets the Nyquist frequency ν_N = 1/(2p), and system MTF is lens MTF times the sinc response of the pixel aperture, with the lens's diffraction cutoff at 1/(λN) for f-number N. Residual secondary spectrum is a wavelength-dependent defocus, so polychromatic MTF must be weighted by the sensor's spectral response, and a Bayer filter halves the sampling rate again for the red and blue channels.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要鏡頭在綠光達到繞射極限，彩色影像就一定清晰。 正確的工程判斷必須回到機制與量級。","textEn":"Misconception: If the lens is diffraction-limited in green, colour images will be sharp. Sound engineering judgement goes back to mechanism and magnitude.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"關於「依感測器匹配設計與 MTF 判準」，下列哪一項敘述正確？","questionEn":"Which statement about \"Sensor-matched design and MTF criteria\" is correct?","options":["只要鏡頭在綠光達到繞射極限，彩色影像就一定清晰。","HeNe 干涉儀量到的波前合格，就代表整個可見光波段都合格。","相機用的消色差透鏡要以感測器取樣來評判：像素間距 p 決定 Nyquist 頻率 ν_N = 1/(2p)，系統 MTF 等於鏡頭 MTF 乘像素孔徑的 sinc 響應。"],"optionsEn":["If the lens is diffraction-limited in green, colour images will be sharp.","A wavefront pass at 632.8 nm means the lens passes across the visible band.","An achromat for a camera must be judged against sensor sampling: pixel pitch p sets the Nyquist frequency ν_N = 1/(2p), and system MTF is lens MTF times the sinc response of the pixel aperture, with the lens's diffraction cutoff at 1/(λN) for f-number N."],"answer":2,"explanation":"相機用的消色差透鏡要以感測器取樣來評判：像素間距 p 決定 Nyquist 頻率 ν_N = 1/(2p)，系統 MTF 等於鏡頭 MTF 乘像素孔徑的 sinc 響應；鏡頭在 f 數 N 的繞射截止頻率為 1/(λN)。 其餘選項是常見誤解。","explanationEn":"An achromat for a camera must be judged against sensor sampling: pixel pitch p sets the Nyquist frequency ν_N = 1/(2p), and system MTF is lens MTF times the sinc response of the pixel aperture, with the lens's diffraction cutoff at 1/(λN) for f-number N. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":29},{"id":"a405-v12-18","title":"依感測器匹配設計與 MTF 判準：定量估算","titleEn":"Sensor-matched design and MTF criteria: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-17"],"objective":"以數值模型估算「感測器像素與 MTF」的關鍵量，並判斷參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Sensor pixels and MTF” with a numerical model and judge the direction and size of changes when a parameter moves.","instruction":"依下列模型逐步重算：p = 3.45 µm，ν_N = 145 lp/mm；f/4、0.55 µm 截止 455 lp/mm，繞射 MTF(145) ≈ 0.60，像素 sinc 0.64，未計像差已只剩 0.38。N-BK7/F2、f = 100 mm 對焦在 d 線時，C、F 離焦 50 µm，W₀₂₀ = Δz/(8N²λ) 分別為 0.60λ 與 0.80λ，Nyquist MTF 只剩 0.05 與 0.02；改用 N-FK51A/N-KZFS4 雙合，色焦差 14.2 µm，C、F 為 0.47 與 0.55。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係。","instructionEn":"Recalculate step by step: p = 3.45 µm gives ν_N = 145 lp/mm; at f/4 and 0.55 µm the cutoff is 455 lp/mm, diffraction MTF(145) ≈ 0.60 and pixel sinc 0.64, already 0.38 before aberrations. An N-BK7/F2 doublet at f = 100 mm focused on the d line leaves C and F 50 µm out, W₀₂₀ = Δz/(8N²λ) of 0.60λ and 0.80λ, so their Nyquist MTF falls to 0.05 and 0.02; an N-FK51A/N-KZFS4 doublet has a 14.2 µm colour spread and gives 0.47 and 0.55. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, and state whether the dependence is linear, quadratic or steeper.","observation":"如何核對：以斜邊法在實際感測器上量 MTF，分別取紅、綠、藍通道，或在 MTF 量測台上配窄帶濾光片逐波長量；每個波長做穿焦掃描求最佳焦點位置，直接量出色焦差並與 50 µm 或 14.2 µm 的設計值比較；量測頻率至少涵蓋 Nyquist 與其一半，並在中心與 70% 視場各量一次。","observationEn":"How to cross-check: Measure MTF on the actual sensor by the slanted-edge method for the red, green and blue channels separately, or on an MTF bench with narrow-band filters wavelength by wavelength; run a through-focus scan per wavelength to locate best focus, measuring the colour focus spread directly against the 50 µm or 14.2 µm design value; cover at least Nyquist and half Nyquist, at the centre and at 70% field.","failure":"計算陷阱：單位換算錯誤、把教學假設當成設備規格，或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit conversion slips, treating teaching assumptions as equipment specifications, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與物理解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with a physical explanation.","knowledge":[{"id":"a405-v12-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"p = 3.45 µm，ν_N = 145 lp/mm；f/4、0.55 µm 截止 455 lp/mm，繞射 MTF(145) ≈ 0.60，像素 sinc 0.64，未計像差已只剩 0.38。N-BK7/F2、f = 100 mm 對焦在 d 線時，C、F 離焦 50 µm，W₀₂₀ = Δz/(8N²λ) 分別為 0.60λ 與 0.80λ，Nyquist MTF 只剩 0.05 與 0.02；改用 N-FK51A/N-KZFS4 雙合，色焦差 14.2 µm，C、F 為 0.47 與 0.55。","textEn":"p = 3.45 µm gives ν_N = 145 lp/mm; at f/4 and 0.55 µm the cutoff is 455 lp/mm, diffraction MTF(145) ≈ 0.60 and pixel sinc 0.64, already 0.38 before aberrations. An N-BK7/F2 doublet at f = 100 mm focused on the d line leaves C and F 50 µm out, W₀₂₀ = Δz/(8N²λ) of 0.60λ and 0.80λ, so their Nyquist MTF falls to 0.05 and 0.02; an N-FK51A/N-KZFS4 doublet has a 14.2 µm colour spread and gives 0.47 and 0.55.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設；套用到實際設備前，必須重新取得規格、操作條件與不確定度。","textEn":"These numbers are teaching assumptions; before applying them to real equipment, obtain the actual specifications, operating conditions and uncertainties.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"依「依感測器匹配設計與 MTF 判準」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Sensor-matched design and MTF criteria\", which statement holds?","options":["p = 3.45 µm，ν_N = 145 lp/mm。","量到的 MTF 只要比規格高一點點，就一定可以放行。","玻璃的熱膨脹很小，所以溫度變化不會讓焦點移動。"],"optionsEn":["p = 3.45 µm gives ν_N = 145 lp/mm; at f/4 and 0.55 µm the cutoff is 455 lp/mm, diffraction MTF(145) ≈ 0.60 and pixel sinc 0.64, already 0.38 before aberrations.","A lens whose measured MTF is just above spec can always be released.","Glass expands so little that temperature changes cannot move the focus."],"answer":0,"explanation":"p = 3.45 µm，ν_N = 145 lp/mm；f/4、0.55 µm 截止 455 lp/mm，繞射 MTF(145) ≈ 0.60，像素 sinc 0.64，未計像差已只剩 0.38。 重算時請保留單位。","explanationEn":"p = 3.45 µm gives ν_N = 145 lp/mm; at f/4 and 0.55 µm the cutoff is 455 lp/mm, diffraction MTF(145) ≈ 0.60 and pixel sinc 0.64, already 0.38 before aberrations. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":30},{"id":"a405-v12-19","title":"依感測器匹配設計與 MTF 判準：量測與驗證","titleEn":"Sensor-matched design and MTF criteria: measurement and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-18"],"objective":"設計一項可重複的量測，驗證「感測器像素與 MTF」是否符合模型預期，並訂出允收準則。","objectiveEn":"Design a repeatable measurement that verifies whether “Sensor pixels and MTF” meets the model expectation, and set acceptance criteria.","instruction":"以斜邊法在實際感測器上量 MTF，分別取紅、綠、藍通道，或在 MTF 量測台上配窄帶濾光片逐波長量；每個波長做穿焦掃描求最佳焦點位置，直接量出色焦差並與 50 µm 或 14.2 µm 的設計值比較；量測頻率至少涵蓋 Nyquist 與其一半，並在中心與 70% 視場各量一次。 師傅任務：把上述方法寫成量測計畫，列出儀器、基準件或參考樣品、步驟、比較對象與允收準則，並估計三項主要不確定度來源。","instructionEn":"Measure MTF on the actual sensor by the slanted-edge method for the red, green and blue channels separately, or on an MTF bench with narrow-band filters wavelength by wavelength; run a through-focus scan per wavelength to locate best focus, measuring the colour focus spread directly against the 50 µm or 14.2 µm design value; cover at least Nyquist and half Nyquist, at the centre and at 70% field. Mentor task: turn this into a measurement plan listing instruments, reference artefacts or samples, procedure, comparison baseline and acceptance criteria, and estimate the three largest uncertainty contributions.","observation":"注意干擾：以 N-BK7/F2 雙合搭配 3.45 µm 像素與 f/4，紅藍通道模糊，高對比邊緣出現紫邊；若規格只寫 546 nm 單色 MTF，鏡頭在檢驗台上全數合格，裝上相機後彩色影像卻不合格，責任在規格而非製造。","observationEn":"Watch for interference: Pairing an N-BK7/F2 doublet with 3.45 µm pixels at f/4 blurs the red and blue channels and puts purple fringes on high-contrast edges; a specification written only as 546 nm monochromatic MTF lets every lens pass on the bench while colour images fail in the camera, a fault of the specification rather than manufacturing.","failure":"驗證陷阱：只量一次、沒有可追溯的基準，或不記錄環境條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Verification traps: a single measurement, no traceable reference, or unrecorded environmental conditions make real deviations indistinguishable from measurement error.","check":"提交量測計畫：儀器、基準、步驟、允收準則與不確定度預算，並說明如何判定合格或不合格。","checkEn":"Submit the measurement plan: instruments, reference, procedure, acceptance criteria and uncertainty budget, with the pass/fail decision rule.","knowledge":[{"id":"a405-v12-19-k1","title":"驗證方法","titleEn":"Verification method","text":"以斜邊法在實際感測器上量 MTF，分別取紅、綠、藍通道，或在 MTF 量測台上配窄帶濾光片逐波長量；每個波長做穿焦掃描求最佳焦點位置，直接量出色焦差並與 50 µm 或 14.2 µm 的設計值比較；量測頻率至少涵蓋 Nyquist 與其一半，並在中心與 70% 視場各量一次。","textEn":"Measure MTF on the actual sensor by the slanted-edge method for the red, green and blue channels separately, or on an MTF bench with narrow-band filters wavelength by wavelength; run a through-focus scan per wavelength to locate best focus, measuring the colour focus spread directly against the 50 µm or 14.2 µm design value; cover at least Nyquist and half Nyquist, at the centre and at 70% field.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-19-k2","title":"允收與不確定度","titleEn":"Acceptance and uncertainty","text":"允收準則必須在量測前訂定，並與擴充不確定度一起陳述；比較基準需可追溯。","textEn":"Acceptance criteria are fixed before measuring and stated together with expanded uncertainty; the comparison reference must be traceable.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"要驗證「依感測器匹配設計與 MTF 判準」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Sensor-matched design and MTF criteria\"?","options":["允收準則可以等看到量測數據後再決定。","以斜邊法在實際感測器上量 MTF，分別取紅、綠、藍通道，或在 MTF 量測台上配窄帶濾光片逐波長量。","空氣間隔雙合只是沒上膠的膠合透鏡，光學性能完全相同。"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Measure MTF on the actual sensor by the slanted-edge method for the red, green and blue channels separately, or on an MTF bench with narrow-band filters wavelength by wavelength.","An air-spaced doublet is just an uncemented cemented doublet with identical optics."],"answer":1,"explanation":"以斜邊法在實際感測器上量 MTF，分別取紅、綠、藍通道，或在 MTF 量測台上配窄帶濾光片逐波長量；每個波長做穿焦掃描求最佳焦點位置，直接量出色焦差並與 50 µm 或 14.2 µm 的設計值比較；量測頻率至少涵蓋 Nyquist 與其一半，並在中心與 70% 視場各量一次。 驗證需要基準、重複性與允收準則。","explanationEn":"Measure MTF on the actual sensor by the slanted-edge method for the red, green and blue channels separately, or on an MTF bench with narrow-band filters wavelength by wavelength; run a through-focus scan per wavelength to locate best focus, measuring the colour focus spread directly against the 50 µm or 14.2 µm design value; cover at least Nyquist and half Nyquist, at the centre and at 70% field. Verification needs a reference, repeatability and acceptance criteria."},"unit":5,"unitFacet":"verification","order":3,"sequence":31},{"id":"a405-v12-20","title":"依感測器匹配設計與 MTF 判準：失效診斷","titleEn":"Sensor-matched design and MTF criteria: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-19"],"objective":"從症狀倒推「感測器像素與 MTF」的失效原因，提出能區分原因的檢查與矯正措施。","objectiveEn":"Work back from symptoms to the failure causes of “Sensor pixels and MTF” and propose discriminating checks and corrective actions.","instruction":"以 N-BK7/F2 雙合搭配 3.45 µm 像素與 f/4，紅藍通道模糊，高對比邊緣出現紫邊；若規格只寫 546 nm 單色 MTF，鏡頭在檢驗台上全數合格，裝上相機後彩色影像卻不合格，責任在規格而非製造。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測，以及矯正與預防措施；並說明此失效如何影響整個系統的性能、良率或安全。","instructionEn":"Pairing an N-BK7/F2 doublet with 3.45 µm pixels at f/4 blurs the red and blue channels and puts purple fringes on high-contrast edges; a specification written only as 546 nm monochromatic MTF lets every lens pass on the bench while colour images fail in the camera, a fault of the specification rather than manufacturing. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system performance, yield or safety.","observation":"連結機制：因此規格應寫成在 Nyquist 或其一半、中心與邊緣的多色 MTF，並要求各色焦點散佈落在 ±2λN² 的像素尺度景深內。","observationEn":"Link to the mechanism: The specification should therefore state polychromatic MTF at Nyquist or half Nyquist at centre and edge, and require the colour focus spread to fall within the pixel-scale depth of focus ±2λN².","failure":"誤判風險：若相信「只要鏡頭在綠光達到繞射極限，彩色影像就一定清晰。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"If the lens is diffraction-limited in green, colour images will be sharp.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，並指出哪一項量測能最快確認根因、如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement that confirms the root cause fastest, and state how recurrence is prevented.","knowledge":[{"id":"a405-v12-20-k1","title":"失效模式","titleEn":"Failure mode","text":"以 N-BK7/F2 雙合搭配 3.45 µm 像素與 f/4，紅藍通道模糊，高對比邊緣出現紫邊；若規格只寫 546 nm 單色 MTF，鏡頭在檢驗台上全數合格，裝上相機後彩色影像卻不合格，責任在規格而非製造。","textEn":"Pairing an N-BK7/F2 doublet with 3.45 µm pixels at f/4 blurs the red and blue channels and puts purple fringes on high-contrast edges; a specification written only as 546 nm monochromatic MTF lets every lens pass on the bench while colour images fail in the camera, a fault of the specification rather than manufacturing.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測確認；只更換零件或放寬參數可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement; merely swapping parts or relaxing limits can mask the problem.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"在「依感測器匹配設計與 MTF 判準」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Sensor-matched design and MTF criteria\" misbehaves, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","HeNe 干涉儀量到的波前合格，就代表整個可見光波段都合格。","以 N-BK7/F2 雙合搭配 3.45 µm 像素與 f/4，紅藍通道模糊，高對比邊緣出現紫邊。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","A wavefront pass at 632.8 nm means the lens passes across the visible band.","Pairing an N-BK7/F2 doublet with 3.45 µm pixels at f/4 blurs the red and blue channels and puts purple fringes on high-contrast edges."],"answer":2,"explanation":"以 N-BK7/F2 雙合搭配 3.45 µm 像素與 f/4，紅藍通道模糊，高對比邊緣出現紫邊；若規格只寫 546 nm 單色 MTF，鏡頭在檢驗台上全數合格，裝上相機後彩色影像卻不合格，責任在規格而非製造。 需以量測區分可能原因。","explanationEn":"Pairing an N-BK7/F2 doublet with 3.45 µm pixels at f/4 blurs the red and blue channels and puts purple fringes on high-contrast edges; a specification written only as 546 nm monochromatic MTF lets every lens pass on the bench while colour images fail in the camera, a fault of the specification rather than manufacturing. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":32},{"id":"a405-v12-21","title":"干涉儀穿透波前量測與波長換算：原理與系統邊界","titleEn":"Interferometric transmitted-wavefront test and wavelength conversion: mechanism and system boundary","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-20"],"objective":"說明「雙程 Fizeau 穿透波前」如何決定消色差透鏡設計的關鍵性能，並畫出其輸入、輸出與邊界。","objectiveEn":"Explain how “Double-pass Fizeau transmitted wavefront” determines the key performance of “Achromatic lens design”, and map its inputs, outputs and boundaries.","instruction":"穿透波前誤差通常用 632.8 nm 的 Fizeau 或 Twyman–Green 干涉儀量：平行測試光穿過鏡片聚焦到參考返回球，原路折返再穿過鏡片一次，所以量到的光程差是單程的兩倍。Zernike 擬合可把傾斜與離焦移除，剩下的像散、彗差與球差分別指向應力、定心與曲率或間距問題。但 HeNe 測試是單色的，看不到色差；它的焦點位置也與設計波長不同，球差還會隨波長改變（色球差），所以 632.8 nm 的合格判定必須依設計模型換算到使用波段。 師傅任務：以方塊圖畫出能量或訊號通過「雙程 Fizeau 穿透波前」的路徑，標出哪些量由設計決定、哪些由環境或製造決定，再用三句話寫出機制摘要。","instructionEn":"Transmitted wavefront error is usually measured with a 632.8 nm Fizeau or Twyman–Green interferometer: the collimated test beam passes through the lens to focus on a reference return sphere and comes back through the lens, so the measured optical path difference is twice the single-pass value. A Zernike fit removes tilt and focus, and the remaining astigmatism, coma and spherical terms point to stress, centring and radius or spacing problems respectively. But a HeNe test is monochromatic and blind to colour; its focus differs from the design wavelength's, and spherical aberration varies with wavelength (spherochromatism), so a pass at 632.8 nm must be converted to the working band through the design model. Mentor task: draw a block diagram of the energy or signal path through “Double-pass Fizeau transmitted wavefront”, mark which quantities are fixed by design and which by environment or fabrication, then summarise the mechanism in three sentences.","observation":"量級提示：雙程量得 0.10λ rms（632.8 nm），單程 0.05λ = 31.6 nm；換到 546 nm 為 0.058λ，Strehl ≈ exp[−(2π × 0.058)²] ≈ 0.876；Maréchal 0.8 要求在 546 nm ≤ λ/14 = 39 nm。","observationEn":"Order-of-magnitude cue: A double-pass reading of 0.10λ rms at 632.8 nm is 0.05λ = 31.6 nm single pass, or 0.058λ at 546 nm, giving Strehl ≈ exp[−(2π × 0.058)²] ≈ 0.876; a Maréchal 0.8 requires ≤ λ/14 = 39 nm at 546 nm.","failure":"常見誤解：「HeNe 干涉儀量到的波前合格，就代表整個可見光波段都合格。」這個說法忽略了上述機制；請在方塊圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A wavefront pass at 632.8 nm means the lens passes across the visible band.\" It ignores the mechanism above; mark on your block diagram where it breaks down.","check":"方塊圖標明「雙程 Fizeau 穿透波前」的輸入、輸出與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The block diagram shows inputs, outputs and boundaries of “Double-pass Fizeau transmitted wavefront”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"a405-v12-21-k1","title":"干涉儀穿透波前量測與波長換算","titleEn":"Interferometric transmitted-wavefront test and wavelength conversion","text":"穿透波前誤差通常用 632.8 nm 的 Fizeau 或 Twyman–Green 干涉儀量：平行測試光穿過鏡片聚焦到參考返回球，原路折返再穿過鏡片一次，所以量到的光程差是單程的兩倍。Zernike 擬合可把傾斜與離焦移除，剩下的像散、彗差與球差分別指向應力、定心與曲率或間距問題。","textEn":"Transmitted wavefront error is usually measured with a 632.8 nm Fizeau or Twyman–Green interferometer: the collimated test beam passes through the lens to focus on a reference return sphere and comes back through the lens, so the measured optical path difference is twice the single-pass value. A Zernike fit removes tilt and focus, and the remaining astigmatism, coma and spherical terms point to stress, centring and radius or spacing problems respectively.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：HeNe 干涉儀量到的波前合格，就代表整個可見光波段都合格。 正確的工程判斷必須回到機制與量級。","textEn":"Misconception: A wavefront pass at 632.8 nm means the lens passes across the visible band. Sound engineering judgement goes back to mechanism and magnitude.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"關於「干涉儀穿透波前量測與波長換算」，下列哪一項敘述正確？","questionEn":"Which statement about \"Interferometric transmitted-wavefront test and wavelength conversion\" is correct?","options":["穿透波前誤差通常用 632.8 nm 的 Fizeau 或 Twyman–Green 干涉儀量：平行測試光穿過鏡片聚焦到參考返回球，原路折返再穿過鏡片一次，所以量到的光程差是單程的兩倍。","HeNe 干涉儀量到的波前合格，就代表整個可見光波段都合格。","只要鍍了抗反射膜，就不會出現鬼影。"],"optionsEn":["Transmitted wavefront error is usually measured with a 632.8 nm Fizeau or Twyman–Green interferometer: the collimated test beam passes through the lens to focus on a reference return sphere and comes back through the lens, so the measured optical path difference is twice the single-pass value.","A wavefront pass at 632.8 nm means the lens passes across the visible band.","Once an antireflection coating is applied, ghosts cannot appear."],"answer":0,"explanation":"穿透波前誤差通常用 632.8 nm 的 Fizeau 或 Twyman–Green 干涉儀量：平行測試光穿過鏡片聚焦到參考返回球，原路折返再穿過鏡片一次，所以量到的光程差是單程的兩倍。 其餘選項是常見誤解。","explanationEn":"Transmitted wavefront error is usually measured with a 632.8 nm Fizeau or Twyman–Green interferometer: the collimated test beam passes through the lens to focus on a reference return sphere and comes back through the lens, so the measured optical path difference is twice the single-pass value. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":33},{"id":"a405-v12-22","title":"干涉儀穿透波前量測與波長換算：定量估算","titleEn":"Interferometric transmitted-wavefront test and wavelength conversion: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-21"],"objective":"以數值模型估算「雙程 Fizeau 穿透波前」的關鍵量，並判斷參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Double-pass Fizeau transmitted wavefront” with a numerical model and judge the direction and size of changes when a parameter moves.","instruction":"依下列模型逐步重算：雙程量得 0.10λ rms（632.8 nm），單程 0.05λ = 31.6 nm；換到 546 nm 為 0.058λ，Strehl ≈ exp[−(2π × 0.058)²] ≈ 0.876；Maréchal 0.8 要求在 546 nm ≤ λ/14 = 39 nm。N-BK7/F2、f = 100 mm 雙合在 632.8 nm 的焦點位於 d 焦點後 28.8 µm，返回球須放在此處，這個焦點偏移本身也能核對玻璃組合是否正確。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係。","instructionEn":"Recalculate step by step: A double-pass reading of 0.10λ rms at 632.8 nm is 0.05λ = 31.6 nm single pass, or 0.058λ at 546 nm, giving Strehl ≈ exp[−(2π × 0.058)²] ≈ 0.876; a Maréchal 0.8 requires ≤ λ/14 = 39 nm at 546 nm. The 632.8 nm focus of an N-BK7/F2 f = 100 mm doublet lies 28.8 µm behind the d focus, so the return sphere must sit there, and that offset itself checks that the glass pair is right. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, and state whether the dependence is linear, quadratic or steeper.","observation":"如何核對：先以旋轉或隨機球平均法校正返回球與參考面的誤差；鏡片在夾具中量 0° 與 180° 兩個方位，相減分離鏡片與系統誤差；把 Zernike 彗差與定心量測結果交叉比對；記錄多次量測的平均與標準差，並把量得的 632.8 nm 焦點位置與模型的 28.8 µm 預測比較。","observationEn":"How to cross-check: Calibrate the return sphere and reference surface first by rotation or random-ball averaging; measure the lens at 0° and 180° in its fixture and difference the results to separate lens from system error; cross-check Zernike coma with centring measurements; log the mean and standard deviation of repeated measurements, and compare the measured 632.8 nm focus position with the modelled 28.8 µm offset.","failure":"計算陷阱：單位換算錯誤、把教學假設當成設備規格，或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit conversion slips, treating teaching assumptions as equipment specifications, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與物理解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with a physical explanation.","knowledge":[{"id":"a405-v12-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"雙程量得 0.10λ rms（632.8 nm），單程 0.05λ = 31.6 nm；換到 546 nm 為 0.058λ，Strehl ≈ exp[−(2π × 0.058)²] ≈ 0.876；Maréchal 0.8 要求在 546 nm ≤ λ/14 = 39 nm。N-BK7/F2、f = 100 mm 雙合在 632.8 nm 的焦點位於 d 焦點後 28.8 µm，返回球須放在此處，這個焦點偏移本身也能核對玻璃組合是否正確。","textEn":"A double-pass reading of 0.10λ rms at 632.8 nm is 0.05λ = 31.6 nm single pass, or 0.058λ at 546 nm, giving Strehl ≈ exp[−(2π × 0.058)²] ≈ 0.876; a Maréchal 0.8 requires ≤ λ/14 = 39 nm at 546 nm. The 632.8 nm focus of an N-BK7/F2 f = 100 mm doublet lies 28.8 µm behind the d focus, so the return sphere must sit there, and that offset itself checks that the glass pair is right.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設；套用到實際設備前，必須重新取得規格、操作條件與不確定度。","textEn":"These numbers are teaching assumptions; before applying them to real equipment, obtain the actual specifications, operating conditions and uncertainties.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"依「干涉儀穿透波前量測與波長換算」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Interferometric transmitted-wavefront test and wavelength conversion\", which statement holds?","options":["只要兩片玻璃的阿貝數差夠大，就能完全消除二級光譜。","雙程量得 0.10λ rms（632.8 nm），單程 0.05λ = 31.6 nm。","空氣間隔雙合只是沒上膠的膠合透鏡，光學性能完全相同。"],"optionsEn":["A large enough Abbe-number difference between two glasses eliminates the secondary spectrum.","A double-pass reading of 0.10λ rms at 632.8 nm is 0.05λ = 31.6 nm single pass, or 0.058λ at 546 nm, giving Strehl ≈ exp[−(2π × 0.058)²] ≈ 0.876.","An air-spaced doublet is just an uncemented cemented doublet with identical optics."],"answer":1,"explanation":"雙程量得 0.10λ rms（632.8 nm），單程 0.05λ = 31.6 nm；換到 546 nm 為 0.058λ，Strehl ≈ exp[−(2π × 0.058)²] ≈ 0.876；Maréchal 0.8 要求在 546 nm ≤ λ/14 = 39 nm。 重算時請保留單位。","explanationEn":"A double-pass reading of 0.10λ rms at 632.8 nm is 0.05λ = 31.6 nm single pass, or 0.058λ at 546 nm, giving Strehl ≈ exp[−(2π × 0.058)²] ≈ 0.876; a Maréchal 0.8 requires ≤ λ/14 = 39 nm at 546 nm. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":34},{"id":"a405-v12-23","title":"干涉儀穿透波前量測與波長換算：量測與驗證","titleEn":"Interferometric transmitted-wavefront test and wavelength conversion: measurement and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-22"],"objective":"設計一項可重複的量測，驗證「雙程 Fizeau 穿透波前」是否符合模型預期，並訂出允收準則。","objectiveEn":"Design a repeatable measurement that verifies whether “Double-pass Fizeau transmitted wavefront” meets the model expectation, and set acceptance criteria.","instruction":"先以旋轉或隨機球平均法校正返回球與參考面的誤差；鏡片在夾具中量 0° 與 180° 兩個方位，相減分離鏡片與系統誤差；把 Zernike 彗差與定心量測結果交叉比對；記錄多次量測的平均與標準差，並把量得的 632.8 nm 焦點位置與模型的 28.8 µm 預測比較。 師傅任務：把上述方法寫成量測計畫，列出儀器、基準件或參考樣品、步驟、比較對象與允收準則，並估計三項主要不確定度來源。","instructionEn":"Calibrate the return sphere and reference surface first by rotation or random-ball averaging; measure the lens at 0° and 180° in its fixture and difference the results to separate lens from system error; cross-check Zernike coma with centring measurements; log the mean and standard deviation of repeated measurements, and compare the measured 632.8 nm focus position with the modelled 28.8 µm offset. Mentor task: turn this into a measurement plan listing instruments, reference artefacts or samples, procedure, comparison baseline and acceptance criteria, and estimate the three largest uncertainty contributions.","observation":"注意干擾：忘記把雙程結果除以 2 或沒扣除參考面誤差，合格鏡片被誤判報廢；鏡片在 632.8 nm 合格卻在 486 nm 因色球差不合格；測試夾具夾得太緊，量到的像散其實是夾持應力，卻被歸咎於拋光。","observationEn":"Watch for interference: Forgetting to halve the double-pass result or to subtract reference error scraps good lenses; a lens passes at 632.8 nm but fails at 486 nm through spherochromatism; an over-tight test fixture produces astigmatism that is really clamping stress yet is blamed on polishing.","failure":"驗證陷阱：只量一次、沒有可追溯的基準，或不記錄環境條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Verification traps: a single measurement, no traceable reference, or unrecorded environmental conditions make real deviations indistinguishable from measurement error.","check":"提交量測計畫：儀器、基準、步驟、允收準則與不確定度預算，並說明如何判定合格或不合格。","checkEn":"Submit the measurement plan: instruments, reference, procedure, acceptance criteria and uncertainty budget, with the pass/fail decision rule.","knowledge":[{"id":"a405-v12-23-k1","title":"驗證方法","titleEn":"Verification method","text":"先以旋轉或隨機球平均法校正返回球與參考面的誤差；鏡片在夾具中量 0° 與 180° 兩個方位，相減分離鏡片與系統誤差；把 Zernike 彗差與定心量測結果交叉比對；記錄多次量測的平均與標準差，並把量得的 632.8 nm 焦點位置與模型的 28.8 µm 預測比較。","textEn":"Calibrate the return sphere and reference surface first by rotation or random-ball averaging; measure the lens at 0° and 180° in its fixture and difference the results to separate lens from system error; cross-check Zernike coma with centring measurements; log the mean and standard deviation of repeated measurements, and compare the measured 632.8 nm focus position with the modelled 28.8 µm offset.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-23-k2","title":"允收與不確定度","titleEn":"Acceptance and uncertainty","text":"允收準則必須在量測前訂定，並與擴充不確定度一起陳述；比較基準需可追溯。","textEn":"Acceptance criteria are fixed before measuring and stated together with expanded uncertainty; the comparison reference must be traceable.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"要驗證「干涉儀穿透波前量測與波長換算」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Interferometric transmitted-wavefront test and wavelength conversion\"?","options":["只要模擬結果看起來合理，就可以省略實體量測與校正。","鏡片拋光到正確曲率後自然就是同心的，不需要另外定心。","先以旋轉或隨機球平均法校正返回球與參考面的誤差。"],"optionsEn":["If the simulation looks reasonable, physical measurement and calibration can be skipped.","A lens polished to the right radii is automatically centred.","Calibrate the return sphere and reference surface first by rotation or random-ball averaging."],"answer":2,"explanation":"先以旋轉或隨機球平均法校正返回球與參考面的誤差；鏡片在夾具中量 0° 與 180° 兩個方位，相減分離鏡片與系統誤差；把 Zernike 彗差與定心量測結果交叉比對；記錄多次量測的平均與標準差，並把量得的 632.8 nm 焦點位置與模型的 28.8 µm 預測比較。 驗證需要基準、重複性與允收準則。","explanationEn":"Calibrate the return sphere and reference surface first by rotation or random-ball averaging; measure the lens at 0° and 180° in its fixture and difference the results to separate lens from system error; cross-check Zernike coma with centring measurements; log the mean and standard deviation of repeated measurements, and compare the measured 632.8 nm focus position with the modelled 28.8 µm offset. Verification needs a reference, repeatability and acceptance criteria."},"unit":6,"unitFacet":"verification","order":7,"sequence":35},{"id":"a405-v12-24","title":"干涉儀穿透波前量測與波長換算：失效診斷","titleEn":"Interferometric transmitted-wavefront test and wavelength conversion: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-23"],"objective":"從症狀倒推「雙程 Fizeau 穿透波前」的失效原因，提出能區分原因的檢查與矯正措施。","objectiveEn":"Work back from symptoms to the failure causes of “Double-pass Fizeau transmitted wavefront” and propose discriminating checks and corrective actions.","instruction":"忘記把雙程結果除以 2 或沒扣除參考面誤差，合格鏡片被誤判報廢；鏡片在 632.8 nm 合格卻在 486 nm 因色球差不合格；測試夾具夾得太緊，量到的像散其實是夾持應力，卻被歸咎於拋光。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測，以及矯正與預防措施；並說明此失效如何影響整個系統的性能、良率或安全。","instructionEn":"Forgetting to halve the double-pass result or to subtract reference error scraps good lenses; a lens passes at 632.8 nm but fails at 486 nm through spherochromatism; an over-tight test fixture produces astigmatism that is really clamping stress yet is blamed on polishing. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system performance, yield or safety.","observation":"連結機制：但 HeNe 測試是單色的，看不到色差；它的焦點位置也與設計波長不同，球差還會隨波長改變（色球差），所以 632.8 nm 的合格判定必須依設計模型換算到使用波段。","observationEn":"Link to the mechanism: But a HeNe test is monochromatic and blind to colour; its focus differs from the design wavelength's, and spherical aberration varies with wavelength (spherochromatism), so a pass at 632.8 nm must be converted to the working band through the design model.","failure":"誤判風險：若相信「HeNe 干涉儀量到的波前合格，就代表整個可見光波段都合格。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A wavefront pass at 632.8 nm means the lens passes across the visible band.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，並指出哪一項量測能最快確認根因、如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement that confirms the root cause fastest, and state how recurrence is prevented.","knowledge":[{"id":"a405-v12-24-k1","title":"失效模式","titleEn":"Failure mode","text":"忘記把雙程結果除以 2 或沒扣除參考面誤差，合格鏡片被誤判報廢；鏡片在 632.8 nm 合格卻在 486 nm 因色球差不合格；測試夾具夾得太緊，量到的像散其實是夾持應力，卻被歸咎於拋光。","textEn":"Forgetting to halve the double-pass result or to subtract reference error scraps good lenses; a lens passes at 632.8 nm but fails at 486 nm through spherochromatism; an over-tight test fixture produces astigmatism that is really clamping stress yet is blamed on polishing.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測確認；只更換零件或放寬參數可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement; merely swapping parts or relaxing limits can mask the problem.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"在「干涉儀穿透波前量測與波長換算」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Interferometric transmitted-wavefront test and wavelength conversion\" misbehaves, which diagnosis is most reasonable?","options":["忘記把雙程結果除以 2 或沒扣除參考面誤差，合格鏡片被誤判報廢。","只要重新開機或重設軟體，硬體失效也會一併排除。","只要鍍了抗反射膜，就不會出現鬼影。"],"optionsEn":["Forgetting to halve the double-pass result or to subtract reference error scraps good lenses.","Restarting or resetting the software also clears hardware failures.","Once an antireflection coating is applied, ghosts cannot appear."],"answer":0,"explanation":"忘記把雙程結果除以 2 或沒扣除參考面誤差，合格鏡片被誤判報廢；鏡片在 632.8 nm 合格卻在 486 nm 因色球差不合格；測試夾具夾得太緊，量到的像散其實是夾持應力，卻被歸咎於拋光。 需以量測區分可能原因。","explanationEn":"Forgetting to halve the double-pass result or to subtract reference error scraps good lenses; a lens passes at 632.8 nm but fails at 486 nm through spherochromatism; an over-tight test fixture produces astigmatism that is really clamping stress yet is blamed on polishing. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":36}],"order":6},{"id":"a405-v12-s4","title":"系統整合、驗證與工程交接","titleEn":"Integration, validation and engineering handoff","description":"本階段聚焦「雜散光與鬼影分析」與「量產驗收矩陣、保護帶與交接」：先建立機制與定量模型，再設計驗證並診斷失效。","descriptionEn":"This stage covers \"Stray-light and ghost analysis\" and \"Production acceptance matrix, guard bands and handoff\": build the mechanism and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"a405-v12-25","title":"雜散光與鬼影分析：原理與系統邊界","titleEn":"Stray-light and ghost analysis: mechanism and system boundary","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-24"],"objective":"說明「鬼影路徑與邊緣雜散光」如何決定消色差透鏡設計的關鍵性能，並畫出其輸入、輸出與邊界。","objectiveEn":"Explain how “Ghost paths and edge stray light” determines the key performance of “Achromatic lens design”, and map its inputs, outputs and boundaries.","instruction":"每個折射面都會反射一點光，經過兩次反射的光又朝感測器前進，形成亮光源的離焦複本，即鬼影。N 個面之間的二次反射路徑共有 N(N − 1)/2 條；膠合雙合有 3 個面，空氣間隔版有 4 個，再加上感測器保護玻璃與感測器本身，而感測器往往是最強的反射面。鬼影照度取決於兩面反射率與鬼影在感測器上的離焦程度，聚焦在感測器附近的鬼影最危險。另一類雜散光來自研磨鏡緣散射、鏡筒內壁與螺紋，以及膠中的氣泡。分析時先用近軸鬼影追跡找出鬼影焦點，再以非序列光線追跡估算照度。 師傅任務：以方塊圖畫出能量或訊號通過「鬼影路徑與邊緣雜散光」的路徑，標出哪些量由設計決定、哪些由環境或製造決定，再用三句話寫出機制摘要。","instructionEn":"Every refracting surface reflects a little light, and light reflected twice heads back toward the sensor as an out-of-focus copy of a bright source, a ghost. Among N surfaces there are N(N − 1)/2 two-bounce paths; a cemented doublet has 3 surfaces and an air-spaced one 4, plus the sensor cover glass and the sensor itself, which is often the strongest reflector. Ghost irradiance depends on the two reflectances and how defocused the ghost is at the sensor, and a ghost that focuses near the sensor is the most dangerous. Other stray light comes from scatter off ground lens edges, barrel walls and threads, and bubbles in the cement. Analysis starts with paraxial ghost tracing to locate ghost foci and then estimates irradiance by non-sequential ray tracing. Mentor task: draw a block diagram of the energy or signal path through “Ghost paths and edge stray light”, mark which quantities are fixed by design and which by environment or fabrication, then summarise the mechanism in three sentences.","observation":"量級提示：路徑數：膠合 3 面有 3 條、空氣間隔 4 面有 6 條；雙合加 2 面保護玻璃與感測器共 6 面，15 條。","observationEn":"Order-of-magnitude cue: Paths: 3 for a cemented 3-surface doublet and 6 for an air-spaced 4-surface one; a doublet plus a 2-surface cover glass and the sensor makes 6 surfaces and 15 paths.","failure":"常見誤解：「只要鍍了抗反射膜，就不會出現鬼影。」這個說法忽略了上述機制；請在方塊圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Once an antireflection coating is applied, ghosts cannot appear.\" It ignores the mechanism above; mark on your block diagram where it breaks down.","check":"方塊圖標明「鬼影路徑與邊緣雜散光」的輸入、輸出與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The block diagram shows inputs, outputs and boundaries of “Ghost paths and edge stray light”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"a405-v12-25-k1","title":"雜散光與鬼影分析","titleEn":"Stray-light and ghost analysis","text":"每個折射面都會反射一點光，經過兩次反射的光又朝感測器前進，形成亮光源的離焦複本，即鬼影。N 個面之間的二次反射路徑共有 N(N − 1)/2 條；膠合雙合有 3 個面，空氣間隔版有 4 個，再加上感測器保護玻璃與感測器本身，而感測器往往是最強的反射面。","textEn":"Every refracting surface reflects a little light, and light reflected twice heads back toward the sensor as an out-of-focus copy of a bright source, a ghost. Among N surfaces there are N(N − 1)/2 two-bounce paths; a cemented doublet has 3 surfaces and an air-spaced one 4, plus the sensor cover glass and the sensor itself, which is often the strongest reflector.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要鍍了抗反射膜，就不會出現鬼影。 正確的工程判斷必須回到機制與量級。","textEn":"Misconception: Once an antireflection coating is applied, ghosts cannot appear. Sound engineering judgement goes back to mechanism and magnitude.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"關於「雜散光與鬼影分析」，下列哪一項敘述正確？","questionEn":"Which statement about \"Stray-light and ghost analysis\" is correct?","options":["只要鍍了抗反射膜，就不會出現鬼影。","每個折射面都會反射一點光，經過兩次反射的光又朝感測器前進，形成亮光源的離焦複本，即鬼影。","量到的 MTF 只要比規格高一點點，就一定可以放行。"],"optionsEn":["Once an antireflection coating is applied, ghosts cannot appear.","Every refracting surface reflects a little light, and light reflected twice heads back toward the sensor as an out-of-focus copy of a bright source, a ghost.","A lens whose measured MTF is just above spec can always be released."],"answer":1,"explanation":"每個折射面都會反射一點光，經過兩次反射的光又朝感測器前進，形成亮光源的離焦複本，即鬼影。 其餘選項是常見誤解。","explanationEn":"Every refracting surface reflects a little light, and light reflected twice heads back toward the sensor as an out-of-focus copy of a bright source, a ghost. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":37},{"id":"a405-v12-26","title":"雜散光與鬼影分析：定量估算","titleEn":"Stray-light and ghost analysis: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-25"],"objective":"以數值模型估算「鬼影路徑與邊緣雜散光」的關鍵量，並判斷參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Ghost paths and edge stray light” with a numerical model and judge the direction and size of changes when a parameter moves.","instruction":"依下列模型逐步重算：路徑數：膠合 3 面有 3 條、空氣間隔 4 面有 6 條；雙合加 2 面保護玻璃與感測器共 6 面，15 條。感測器（R = 4%）與鏡頭後表面（鍍膜 R = 0.5%）之間的鬼影能量比 2×10⁻⁴；若 50 µm 的 LED 像變成 0.5 mm 的鬼影圓盤，峰值比 2×10⁻⁴ × (50/500)² = 2×10⁻⁶；LED 超出滿井 1000 倍時，鬼影達滿井的 0.2%，在 12 位元感測器約 8 LSB，肉眼可見。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係。","instructionEn":"Recalculate step by step: Paths: 3 for a cemented 3-surface doublet and 6 for an air-spaced 4-surface one; a doublet plus a 2-surface cover glass and the sensor makes 6 surfaces and 15 paths. A ghost between the sensor (R = 4%) and the rear lens surface (coated R = 0.5%) carries an energy ratio of 2×10⁻⁴; if a 50 µm LED image becomes a 0.5 mm ghost disc the peak ratio is 2×10⁻⁴ × (50/500)² = 2×10⁻⁶, and with the LED 1000 times over full well the ghost reaches 0.2% of full well, about 8 LSB on a 12-bit sensor and visible. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, and state whether the dependence is linear, quadratic or steeper.","observation":"如何核對：以準直的強光源在多個視場角掃描，用長曝光或高動態範圍拍攝鏡頭加感測器的影像，標出鬼影位置與大小並與鬼影追跡比較；以積分球加黑點的方法量面眩光指數；檢查鏡緣是否塗黑、鏡筒內壁是否有消光螺紋，並在紅外波段重複測試，確認鍍膜在感測器全響應範圍內都有效。","observationEn":"How to cross-check: Scan a bright collimated source across several field angles and record lens plus sensor with long exposures or high dynamic range, mark ghost positions and sizes and compare with the ghost trace; measure the veiling-glare index with an integrating sphere and black spot; check that lens edges are blackened and barrel walls carry baffling threads, and repeat in the near infrared to confirm the coating works across the sensor's full response.","failure":"計算陷阱：單位換算錯誤、把教學假設當成設備規格，或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit conversion slips, treating teaching assumptions as equipment specifications, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與物理解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with a physical explanation.","knowledge":[{"id":"a405-v12-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"路徑數：膠合 3 面有 3 條、空氣間隔 4 面有 6 條；雙合加 2 面保護玻璃與感測器共 6 面，15 條。感測器（R = 4%）與鏡頭後表面（鍍膜 R = 0.5%）之間的鬼影能量比 2×10⁻⁴；若 50 µm 的 LED 像變成 0.5 mm 的鬼影圓盤，峰值比 2×10⁻⁴ × (50/500)² = 2×10⁻⁶；LED 超出滿井 1000 倍時，鬼影達滿井的 0.2%，在 12 位元感測器約 8 LSB，肉眼可見。","textEn":"Paths: 3 for a cemented 3-surface doublet and 6 for an air-spaced 4-surface one; a doublet plus a 2-surface cover glass and the sensor makes 6 surfaces and 15 paths. A ghost between the sensor (R = 4%) and the rear lens surface (coated R = 0.5%) carries an energy ratio of 2×10⁻⁴; if a 50 µm LED image becomes a 0.5 mm ghost disc the peak ratio is 2×10⁻⁴ × (50/500)² = 2×10⁻⁶, and with the LED 1000 times over full well the ghost reaches 0.2% of full well, about 8 LSB on a 12-bit sensor and visible.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設；套用到實際設備前，必須重新取得規格、操作條件與不確定度。","textEn":"These numbers are teaching assumptions; before applying them to real equipment, obtain the actual specifications, operating conditions and uncertainties.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"依「雜散光與鬼影分析」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Stray-light and ghost analysis\", which statement holds?","options":["玻璃的熱膨脹很小，所以溫度變化不會讓焦點移動。","鏡片拋光到正確曲率後自然就是同心的，不需要另外定心。","路徑數：膠合 3 面有 3 條、空氣間隔 4 面有 6 條；雙合加 2 面保護玻璃與感測器共 6 面，15 條。"],"optionsEn":["Glass expands so little that temperature changes cannot move the focus.","A lens polished to the right radii is automatically centred.","Paths: 3 for a cemented 3-surface doublet and 6 for an air-spaced 4-surface one."],"answer":2,"explanation":"路徑數：膠合 3 面有 3 條、空氣間隔 4 面有 6 條；雙合加 2 面保護玻璃與感測器共 6 面，15 條。 重算時請保留單位。","explanationEn":"Paths: 3 for a cemented 3-surface doublet and 6 for an air-spaced 4-surface one; a doublet plus a 2-surface cover glass and the sensor makes 6 surfaces and 15 paths. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":38},{"id":"a405-v12-27","title":"雜散光與鬼影分析：量測與驗證","titleEn":"Stray-light and ghost analysis: measurement and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-26"],"objective":"設計一項可重複的量測，驗證「鬼影路徑與邊緣雜散光」是否符合模型預期，並訂出允收準則。","objectiveEn":"Design a repeatable measurement that verifies whether “Ghost paths and edge stray light” meets the model expectation, and set acceptance criteria.","instruction":"以準直的強光源在多個視場角掃描，用長曝光或高動態範圍拍攝鏡頭加感測器的影像，標出鬼影位置與大小並與鬼影追跡比較；以積分球加黑點的方法量面眩光指數；檢查鏡緣是否塗黑、鏡筒內壁是否有消光螺紋，並在紅外波段重複測試，確認鍍膜在感測器全響應範圍內都有效。 師傅任務：把上述方法寫成量測計畫，列出儀器、基準件或參考樣品、步驟、比較對象與允收準則，並估計三項主要不確定度來源。","instructionEn":"Scan a bright collimated source across several field angles and record lens plus sensor with long exposures or high dynamic range, mark ghost positions and sizes and compare with the ghost trace; measure the veiling-glare index with an integrating sphere and black spot; check that lens edges are blackened and barrel walls carry baffling threads, and repeat in the near infrared to confirm the coating works across the sensor's full response. Mentor task: turn this into a measurement plan listing instruments, reference artefacts or samples, procedure, comparison baseline and acceptance criteria, and estimate the three largest uncertainty contributions.","observation":"注意干擾：未塗黑的研磨鏡緣把視場外的強光散射成整片霧光，對比下降；抗反射膜只針對可見光最佳化，感測器在近紅外仍有響應，夜間模式鬼影突然明顯；聚焦在感測器上的鬼影成為與光源反向移動的亮點，被誤判為缺陷像素或目標。","observationEn":"Watch for interference: An unblackened ground edge scatters a bright out-of-field source into a veil of haze that lowers contrast; a coating optimised only for the visible leaves high near-infrared reflectance where the sensor still responds, so ghosts suddenly appear in night mode; a ghost focused on the sensor becomes a bright spot moving opposite to the source, mistaken for a defective pixel or a target.","failure":"驗證陷阱：只量一次、沒有可追溯的基準，或不記錄環境條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Verification traps: a single measurement, no traceable reference, or unrecorded environmental conditions make real deviations indistinguishable from measurement error.","check":"提交量測計畫：儀器、基準、步驟、允收準則與不確定度預算，並說明如何判定合格或不合格。","checkEn":"Submit the measurement plan: instruments, reference, procedure, acceptance criteria and uncertainty budget, with the pass/fail decision rule.","knowledge":[{"id":"a405-v12-27-k1","title":"驗證方法","titleEn":"Verification method","text":"以準直的強光源在多個視場角掃描，用長曝光或高動態範圍拍攝鏡頭加感測器的影像，標出鬼影位置與大小並與鬼影追跡比較；以積分球加黑點的方法量面眩光指數；檢查鏡緣是否塗黑、鏡筒內壁是否有消光螺紋，並在紅外波段重複測試，確認鍍膜在感測器全響應範圍內都有效。","textEn":"Scan a bright collimated source across several field angles and record lens plus sensor with long exposures or high dynamic range, mark ghost positions and sizes and compare with the ghost trace; measure the veiling-glare index with an integrating sphere and black spot; check that lens edges are blackened and barrel walls carry baffling threads, and repeat in the near infrared to confirm the coating works across the sensor's full response.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-27-k2","title":"允收與不確定度","titleEn":"Acceptance and uncertainty","text":"允收準則必須在量測前訂定，並與擴充不確定度一起陳述；比較基準需可追溯。","textEn":"Acceptance criteria are fixed before measuring and stated together with expanded uncertainty; the comparison reference must be traceable.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"要驗證「雜散光與鬼影分析」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Stray-light and ghost analysis\"?","options":["以準直的強光源在多個視場角掃描，用長曝光或高動態範圍拍攝鏡頭加感測器的影像，標出鬼影位置與大小並與鬼影追跡比較。","量測時不必記錄溫度、振動與時間等條件，因為它們不會影響結果。","只要鏡頭在綠光達到繞射極限，彩色影像就一定清晰。"],"optionsEn":["Scan a bright collimated source across several field angles and record lens plus sensor with long exposures or high dynamic range, mark ghost positions and sizes and compare with the ghost trace.","Temperature, vibration and timing need not be recorded because they cannot affect the result.","If the lens is diffraction-limited in green, colour images will be sharp."],"answer":0,"explanation":"以準直的強光源在多個視場角掃描，用長曝光或高動態範圍拍攝鏡頭加感測器的影像，標出鬼影位置與大小並與鬼影追跡比較；以積分球加黑點的方法量面眩光指數；檢查鏡緣是否塗黑、鏡筒內壁是否有消光螺紋，並在紅外波段重複測試，確認鍍膜在感測器全響應範圍內都有效。 驗證需要基準、重複性與允收準則。","explanationEn":"Scan a bright collimated source across several field angles and record lens plus sensor with long exposures or high dynamic range, mark ghost positions and sizes and compare with the ghost trace; measure the veiling-glare index with an integrating sphere and black spot; check that lens edges are blackened and barrel walls carry baffling threads, and repeat in the near infrared to confirm the coating works across the sensor's full response. Verification needs a reference, repeatability and acceptance criteria."},"unit":7,"unitFacet":"verification","order":3,"sequence":39},{"id":"a405-v12-28","title":"雜散光與鬼影分析：失效診斷","titleEn":"Stray-light and ghost analysis: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-27"],"objective":"從症狀倒推「鬼影路徑與邊緣雜散光」的失效原因，提出能區分原因的檢查與矯正措施。","objectiveEn":"Work back from symptoms to the failure causes of “Ghost paths and edge stray light” and propose discriminating checks and corrective actions.","instruction":"未塗黑的研磨鏡緣把視場外的強光散射成整片霧光，對比下降；抗反射膜只針對可見光最佳化，感測器在近紅外仍有響應，夜間模式鬼影突然明顯；聚焦在感測器上的鬼影成為與光源反向移動的亮點，被誤判為缺陷像素或目標。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測，以及矯正與預防措施；並說明此失效如何影響整個系統的性能、良率或安全。","instructionEn":"An unblackened ground edge scatters a bright out-of-field source into a veil of haze that lowers contrast; a coating optimised only for the visible leaves high near-infrared reflectance where the sensor still responds, so ghosts suddenly appear in night mode; a ghost focused on the sensor becomes a bright spot moving opposite to the source, mistaken for a defective pixel or a target. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system performance, yield or safety.","observation":"連結機制：分析時先用近軸鬼影追跡找出鬼影焦點，再以非序列光線追跡估算照度。","observationEn":"Link to the mechanism: Analysis starts with paraxial ghost tracing to locate ghost foci and then estimates irradiance by non-sequential ray tracing.","failure":"誤判風險：若相信「只要鍍了抗反射膜，就不會出現鬼影。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Once an antireflection coating is applied, ghosts cannot appear.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，並指出哪一項量測能最快確認根因、如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement that confirms the root cause fastest, and state how recurrence is prevented.","knowledge":[{"id":"a405-v12-28-k1","title":"失效模式","titleEn":"Failure mode","text":"未塗黑的研磨鏡緣把視場外的強光散射成整片霧光，對比下降；抗反射膜只針對可見光最佳化，感測器在近紅外仍有響應，夜間模式鬼影突然明顯；聚焦在感測器上的鬼影成為與光源反向移動的亮點，被誤判為缺陷像素或目標。","textEn":"An unblackened ground edge scatters a bright out-of-field source into a veil of haze that lowers contrast; a coating optimised only for the visible leaves high near-infrared reflectance where the sensor still responds, so ghosts suddenly appear in night mode; a ghost focused on the sensor becomes a bright spot moving opposite to the source, mistaken for a defective pixel or a target.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測確認；只更換零件或放寬參數可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement; merely swapping parts or relaxing limits can mask the problem.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"在「雜散光與鬼影分析」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Stray-light and ghost analysis\" misbehaves, which diagnosis is most reasonable?","options":["所有異常都來自操作人員失誤，系統設計不需要檢討。","未塗黑的研磨鏡緣把視場外的強光散射成整片霧光，對比下降。","量到的 MTF 只要比規格高一點點，就一定可以放行。"],"optionsEn":["Every anomaly is operator error, so the system design never needs review.","An unblackened ground edge scatters a bright out-of-field source into a veil of haze that lowers contrast.","A lens whose measured MTF is just above spec can always be released."],"answer":1,"explanation":"未塗黑的研磨鏡緣把視場外的強光散射成整片霧光，對比下降；抗反射膜只針對可見光最佳化，感測器在近紅外仍有響應，夜間模式鬼影突然明顯；聚焦在感測器上的鬼影成為與光源反向移動的亮點，被誤判為缺陷像素或目標。 需以量測區分可能原因。","explanationEn":"An unblackened ground edge scatters a bright out-of-field source into a veil of haze that lowers contrast; a coating optimised only for the visible leaves high near-infrared reflectance where the sensor still responds, so ghosts suddenly appear in night mode; a ghost focused on the sensor becomes a bright spot moving opposite to the source, mistaken for a defective pixel or a target. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":40},{"id":"a405-v12-29","title":"量產驗收矩陣、保護帶與交接：原理與系統邊界","titleEn":"Production acceptance matrix, guard bands and handoff: mechanism and system boundary","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-28"],"objective":"說明「驗收矩陣與保護帶」如何決定消色差透鏡設計的關鍵性能，並畫出其輸入、輸出與邊界。","objectiveEn":"Explain how “Acceptance matrix and guard band” determines the key performance of “Achromatic lens design”, and map its inputs, outputs and boundaries.","instruction":"量產驗收把設計轉成可量的門檻：有效焦距與後焦、指定頻率與視場的多色 MTF、軸向色焦差、632.8 nm 穿透波前、定心與視軸、鬼影檢查、熱離焦，以及依 ISO 10110-7 標示的表面瑕疵。量測不確定度必須遠小於公差，測試不確定度比至少 4；下限規格的允收門檻要加上保護帶，即門檻 = 規格 + U，在生產者風險（誤拒好件）與使用者風險（誤收壞件）之間取捨。量測台本身要做重複性與再現性研究，並以標準鏡每日校驗。 師傅任務：以方塊圖畫出能量或訊號通過「驗收矩陣與保護帶」的路徑，標出哪些量由設計決定、哪些由環境或製造決定，再用三句話寫出機制摘要。","instructionEn":"Production acceptance turns the design into measurable gates: effective and back focal length, polychromatic MTF at specified frequencies and fields, axial colour focus spread, 632.8 nm transmitted wavefront, centring and boresight, ghost checks, thermal defocus and surface imperfections stated per ISO 10110-7. Measurement uncertainty must be well below tolerance, with a test uncertainty ratio of at least 4; for a lower-limit specification the acceptance threshold is guard-banded as threshold = spec + U, trading producer risk of rejecting good parts against consumer risk of accepting bad ones. The test bench itself needs a repeatability and reproducibility study and a daily check against a reference lens. Mentor task: draw a block diagram of the energy or signal path through “Acceptance matrix and guard band”, mark which quantities are fixed by design and which by environment or fabrication, then summarise the mechanism in three sentences.","observation":"量級提示：規格：72 lp/mm 多色 MTF ≥ 0.30；量測擴充不確定度 U = 0.03（k = 2），保護帶門檻 0.33。","observationEn":"Order-of-magnitude cue: Specification: polychromatic MTF ≥ 0.30 at 72 lp/mm with expanded uncertainty U = 0.03 (k = 2), so the guard-banded threshold is 0.33.","failure":"常見誤解：「量到的 MTF 只要比規格高一點點，就一定可以放行。」這個說法忽略了上述機制；請在方塊圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A lens whose measured MTF is just above spec can always be released.\" It ignores the mechanism above; mark on your block diagram where it breaks down.","check":"方塊圖標明「驗收矩陣與保護帶」的輸入、輸出與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The block diagram shows inputs, outputs and boundaries of “Acceptance matrix and guard band”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"a405-v12-29-k1","title":"量產驗收矩陣、保護帶與交接","titleEn":"Production acceptance matrix, guard bands and handoff","text":"量產驗收把設計轉成可量的門檻：有效焦距與後焦、指定頻率與視場的多色 MTF、軸向色焦差、632.8 nm 穿透波前、定心與視軸、鬼影檢查、熱離焦，以及依 ISO 10110-7 標示的表面瑕疵。量測不確定度必須遠小於公差，測試不確定度比至少 4；下限規格的允收門檻要加上保護帶，即門檻 = 規格 + U，在生產者風險（誤拒好件）與使用者風險（誤收壞件）之間取捨。","textEn":"Production acceptance turns the design into measurable gates: effective and back focal length, polychromatic MTF at specified frequencies and fields, axial colour focus spread, 632.8 nm transmitted wavefront, centring and boresight, ghost checks, thermal defocus and surface imperfections stated per ISO 10110-7. Measurement uncertainty must be well below tolerance, with a test uncertainty ratio of at least 4; for a lower-limit specification the acceptance threshold is guard-banded as threshold = spec + U, trading producer risk of rejecting good parts against consumer risk of accepting bad ones.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：量到的 MTF 只要比規格高一點點，就一定可以放行。 正確的工程判斷必須回到機制與量級。","textEn":"Misconception: A lens whose measured MTF is just above spec can always be released. Sound engineering judgement goes back to mechanism and magnitude.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"關於「量產驗收矩陣、保護帶與交接」，下列哪一項敘述正確？","questionEn":"Which statement about \"Production acceptance matrix, guard bands and handoff\" is correct?","options":["量到的 MTF 只要比規格高一點點，就一定可以放行。","只要兩片玻璃的阿貝數差夠大，就能完全消除二級光譜。","量產驗收把設計轉成可量的門檻：有效焦距與後焦、指定頻率與視場的多色 MTF、軸向色焦差、632.8 nm 穿透波前、定心與視軸、鬼影檢查、熱離焦，以及依 ISO 10110-7 標示的表面瑕疵。"],"optionsEn":["A lens whose measured MTF is just above spec can always be released.","A large enough Abbe-number difference between two glasses eliminates the secondary spectrum.","Production acceptance turns the design into measurable gates: effective and back focal length, polychromatic MTF at specified frequencies and fields, axial colour focus spread, 632.8 nm transmitted wavefront, centring and boresight, ghost checks, thermal defocus and surface imperfections stated per ISO 10110-7."],"answer":2,"explanation":"量產驗收把設計轉成可量的門檻：有效焦距與後焦、指定頻率與視場的多色 MTF、軸向色焦差、632.8 nm 穿透波前、定心與視軸、鬼影檢查、熱離焦，以及依 ISO 10110-7 標示的表面瑕疵。 其餘選項是常見誤解。","explanationEn":"Production acceptance turns the design into measurable gates: effective and back focal length, polychromatic MTF at specified frequencies and fields, axial colour focus spread, 632.8 nm transmitted wavefront, centring and boresight, ghost checks, thermal defocus and surface imperfections stated per ISO 10110-7. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":41},{"id":"a405-v12-30","title":"量產驗收矩陣、保護帶與交接：定量估算","titleEn":"Production acceptance matrix, guard bands and handoff: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-29"],"objective":"以數值模型估算「驗收矩陣與保護帶」的關鍵量，並判斷參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Acceptance matrix and guard band” with a numerical model and judge the direction and size of changes when a parameter moves.","instruction":"依下列模型逐步重算：規格：72 lp/mm 多色 MTF ≥ 0.30；量測擴充不確定度 U = 0.03（k = 2），保護帶門檻 0.33。若量產平均 0.38、標準差 0.025，有保護帶的良率 Φ((0.38 − 0.33)/0.025) = Φ(2.0) = 97.7%，不加保護帶為 Φ(3.2) = 99.93%，但會放行真值略低於 0.30 的鏡頭。焦距公差 ±0.5 mm、U = 0.1 mm，測試不確定度比 5，符合 ≥ 4 的要求。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係。","instructionEn":"Recalculate step by step: Specification: polychromatic MTF ≥ 0.30 at 72 lp/mm with expanded uncertainty U = 0.03 (k = 2), so the guard-banded threshold is 0.33. With a production mean of 0.38 and standard deviation 0.025, guard-banded yield is Φ((0.38 − 0.33)/0.025) = Φ(2.0) = 97.7%, against Φ(3.2) = 99.93% without a guard band, which would release lenses whose true MTF lies just below 0.30. A focal-length tolerance of ±0.5 mm with U = 0.1 mm gives a test uncertainty ratio of 5, meeting the ≥ 4 requirement. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, and state whether the dependence is linear, quadratic or steeper.","observation":"如何核對：對 MTF 量測台做量測系統分析：10 顆鏡頭 × 3 位操作員 × 3 次重複，計算重複性與再現性佔公差的百分比；每日以標準鏡確認讀值在管制界限內；與客戶的量測台做相關性比對，找出系統偏差；把每顆鏡頭的量測值、玻璃熔次、膠批號與設計模型版本一併記錄到序號。","observationEn":"How to cross-check: Run a measurement-system analysis on the MTF bench with 10 lenses × 3 operators × 3 repeats and compute repeatability and reproducibility as a percentage of tolerance; check daily that the reference lens reads within control limits; correlate with the customer's bench to find systematic bias; record each lens's results with glass melt lot, cement batch and design-model version under its serial number.","failure":"計算陷阱：單位換算錯誤、把教學假設當成設備規格，或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit conversion slips, treating teaching assumptions as equipment specifications, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與物理解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with a physical explanation.","knowledge":[{"id":"a405-v12-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"規格：72 lp/mm 多色 MTF ≥ 0.30；量測擴充不確定度 U = 0.03（k = 2），保護帶門檻 0.33。若量產平均 0.38、標準差 0.025，有保護帶的良率 Φ((0.38 − 0.33)/0.025) = Φ(2.0) = 97.7%，不加保護帶為 Φ(3.2) = 99.93%，但會放行真值略低於 0.30 的鏡頭。焦距公差 ±0.5 mm、U = 0.1 mm，測試不確定度比 5，符合 ≥ 4 的要求。","textEn":"Specification: polychromatic MTF ≥ 0.30 at 72 lp/mm with expanded uncertainty U = 0.03 (k = 2), so the guard-banded threshold is 0.33. With a production mean of 0.38 and standard deviation 0.025, guard-banded yield is Φ((0.38 − 0.33)/0.025) = Φ(2.0) = 97.7%, against Φ(3.2) = 99.93% without a guard band, which would release lenses whose true MTF lies just below 0.30. A focal-length tolerance of ±0.5 mm with U = 0.1 mm gives a test uncertainty ratio of 5, meeting the ≥ 4 requirement.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設；套用到實際設備前，必須重新取得規格、操作條件與不確定度。","textEn":"These numbers are teaching assumptions; before applying them to real equipment, obtain the actual specifications, operating conditions and uncertainties.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"依「量產驗收矩陣、保護帶與交接」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Production acceptance matrix, guard bands and handoff\", which statement holds?","options":["規格：72 lp/mm 多色 MTF ≥ 0.30；量測擴充不確定度 U = 0.03（k = 2），保護帶門檻 0.33。","空氣間隔雙合只是沒上膠的膠合透鏡，光學性能完全相同。","只要鏡頭在綠光達到繞射極限，彩色影像就一定清晰。"],"optionsEn":["Specification: polychromatic MTF ≥ 0.30 at 72 lp/mm with expanded uncertainty U = 0.03 (k = 2), so the guard-banded threshold is 0.33.","An air-spaced doublet is just an uncemented cemented doublet with identical optics.","If the lens is diffraction-limited in green, colour images will be sharp."],"answer":0,"explanation":"規格：72 lp/mm 多色 MTF ≥ 0.30；量測擴充不確定度 U = 0.03（k = 2），保護帶門檻 0.33。 重算時請保留單位。","explanationEn":"Specification: polychromatic MTF ≥ 0.30 at 72 lp/mm with expanded uncertainty U = 0.03 (k = 2), so the guard-banded threshold is 0.33. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":42},{"id":"a405-v12-31","title":"量產驗收矩陣、保護帶與交接：量測與驗證","titleEn":"Production acceptance matrix, guard bands and handoff: measurement and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-30"],"objective":"設計一項可重複的量測，驗證「驗收矩陣與保護帶」是否符合模型預期，並訂出允收準則。","objectiveEn":"Design a repeatable measurement that verifies whether “Acceptance matrix and guard band” meets the model expectation, and set acceptance criteria.","instruction":"對 MTF 量測台做量測系統分析：10 顆鏡頭 × 3 位操作員 × 3 次重複，計算重複性與再現性佔公差的百分比；每日以標準鏡確認讀值在管制界限內；與客戶的量測台做相關性比對，找出系統偏差；把每顆鏡頭的量測值、玻璃熔次、膠批號與設計模型版本一併記錄到序號。 師傅任務：把上述方法寫成量測計畫，列出儀器、基準件或參考樣品、步驟、比較對象與允收準則，並估計三項主要不確定度來源。","instructionEn":"Run a measurement-system analysis on the MTF bench with 10 lenses × 3 operators × 3 repeats and compute repeatability and reproducibility as a percentage of tolerance; check daily that the reference lens reads within control limits; correlate with the customer's bench to find systematic bias; record each lens's results with glass melt lot, cement batch and design-model version under its serial number. Mentor task: turn this into a measurement plan listing instruments, reference artefacts or samples, procedure, comparison baseline and acceptance criteria, and estimate the three largest uncertainty contributions.","observation":"注意干擾：供應商與客戶的 MTF 量測台相差 0.04，整批在進料檢驗被退回；未設保護帶，邊緣件流入產品造成客訴；標準鏡在搬運中受損而讀值偏高，未被察覺下所有鏡頭都被高估。","observationEn":"Watch for interference: Supplier and customer MTF benches differ by 0.04 and whole lots are rejected at incoming inspection; without a guard band marginal parts reach products and return as complaints; a reference lens damaged in handling reads high unnoticed, so every lens is overestimated.","failure":"驗證陷阱：只量一次、沒有可追溯的基準，或不記錄環境條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Verification traps: a single measurement, no traceable reference, or unrecorded environmental conditions make real deviations indistinguishable from measurement error.","check":"提交量測計畫：儀器、基準、步驟、允收準則與不確定度預算，並說明如何判定合格或不合格。","checkEn":"Submit the measurement plan: instruments, reference, procedure, acceptance criteria and uncertainty budget, with the pass/fail decision rule.","knowledge":[{"id":"a405-v12-31-k1","title":"驗證方法","titleEn":"Verification method","text":"對 MTF 量測台做量測系統分析：10 顆鏡頭 × 3 位操作員 × 3 次重複，計算重複性與再現性佔公差的百分比；每日以標準鏡確認讀值在管制界限內；與客戶的量測台做相關性比對，找出系統偏差；把每顆鏡頭的量測值、玻璃熔次、膠批號與設計模型版本一併記錄到序號。","textEn":"Run a measurement-system analysis on the MTF bench with 10 lenses × 3 operators × 3 repeats and compute repeatability and reproducibility as a percentage of tolerance; check daily that the reference lens reads within control limits; correlate with the customer's bench to find systematic bias; record each lens's results with glass melt lot, cement batch and design-model version under its serial number.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-31-k2","title":"允收與不確定度","titleEn":"Acceptance and uncertainty","text":"允收準則必須在量測前訂定，並與擴充不確定度一起陳述；比較基準需可追溯。","textEn":"Acceptance criteria are fixed before measuring and stated together with expanded uncertainty; the comparison reference must be traceable.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"要驗證「量產驗收矩陣、保護帶與交接」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Production acceptance matrix, guard bands and handoff\"?","options":["沿用另一台設備或另一個案例的量測結果，就可視為本系統已完成驗證。","對 MTF 量測台做量測系統分析：10 顆鏡頭 × 3 位操作員 × 3 次重複，計算重複性與再現性佔公差的百分比。","HeNe 干涉儀量到的波前合格，就代表整個可見光波段都合格。"],"optionsEn":["Reusing results from another instrument or another case counts as verifying this system.","Run a measurement-system analysis on the MTF bench with 10 lenses × 3 operators × 3 repeats and compute repeatability and reproducibility as a percentage of tolerance.","A wavefront pass at 632.8 nm means the lens passes across the visible band."],"answer":1,"explanation":"對 MTF 量測台做量測系統分析：10 顆鏡頭 × 3 位操作員 × 3 次重複，計算重複性與再現性佔公差的百分比；每日以標準鏡確認讀值在管制界限內；與客戶的量測台做相關性比對，找出系統偏差；把每顆鏡頭的量測值、玻璃熔次、膠批號與設計模型版本一併記錄到序號。 驗證需要基準、重複性與允收準則。","explanationEn":"Run a measurement-system analysis on the MTF bench with 10 lenses × 3 operators × 3 repeats and compute repeatability and reproducibility as a percentage of tolerance; check daily that the reference lens reads within control limits; correlate with the customer's bench to find systematic bias; record each lens's results with glass melt lot, cement batch and design-model version under its serial number. Verification needs a reference, repeatability and acceptance criteria."},"unit":8,"unitFacet":"verification","order":7,"sequence":43},{"id":"a405-v12-32","title":"量產驗收矩陣、保護帶與交接：失效診斷","titleEn":"Production acceptance matrix, guard bands and handoff: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"],"prerequisiteIds":["a405-v12-31"],"objective":"從症狀倒推「驗收矩陣與保護帶」的失效原因，提出能區分原因的檢查與矯正措施。","objectiveEn":"Work back from symptoms to the failure causes of “Acceptance matrix and guard band” and propose discriminating checks and corrective actions.","instruction":"供應商與客戶的 MTF 量測台相差 0.04，整批在進料檢驗被退回；未設保護帶，邊緣件流入產品造成客訴；標準鏡在搬運中受損而讀值偏高，未被察覺下所有鏡頭都被高估。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測，以及矯正與預防措施；並說明此失效如何影響整個系統的性能、良率或安全。","instructionEn":"Supplier and customer MTF benches differ by 0.04 and whole lots are rejected at incoming inspection; without a guard band marginal parts reach products and return as complaints; a reference lens damaged in handling reads high unnoticed, so every lens is overestimated. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system performance, yield or safety.","observation":"連結機制：量測台本身要做重複性與再現性研究，並以標準鏡每日校驗。","observationEn":"Link to the mechanism: The test bench itself needs a repeatability and reproducibility study and a daily check against a reference lens.","failure":"誤判風險：若相信「量到的 MTF 只要比規格高一點點，就一定可以放行。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A lens whose measured MTF is just above spec can always be released.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，並指出哪一項量測能最快確認根因、如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement that confirms the root cause fastest, and state how recurrence is prevented.","knowledge":[{"id":"a405-v12-32-k1","title":"失效模式","titleEn":"Failure mode","text":"供應商與客戶的 MTF 量測台相差 0.04，整批在進料檢驗被退回；未設保護帶，邊緣件流入產品造成客訴；標準鏡在搬運中受損而讀值偏高，未被察覺下所有鏡頭都被高估。","textEn":"Supplier and customer MTF benches differ by 0.04 and whole lots are rejected at incoming inspection; without a guard band marginal parts reach products and return as complaints; a reference lens damaged in handling reads high unnoticed, so every lens is overestimated.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]},{"id":"a405-v12-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測確認；只更換零件或放寬參數可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement; merely swapping parts or relaxing limits can mask the problem.","sourceIds":["v6-achromat-edmund","v12o-schott-tie-29-refractive-index","v12o-schott-tie-19-dn-dt"]}],"quiz":{"question":"在「量產驗收矩陣、保護帶與交接」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Production acceptance matrix, guard bands and handoff\" misbehaves, which diagnosis is most reasonable?","options":["調高增益或放寬允收值，就能解決大多數異常。","只要兩片玻璃的阿貝數差夠大，就能完全消除二級光譜。","供應商與客戶的 MTF 量測台相差 0.04，整批在進料檢驗被退回。"],"optionsEn":["Raising the gain or widening the acceptance limits solves most anomalies.","A large enough Abbe-number difference between two glasses eliminates the secondary spectrum.","Supplier and customer MTF benches differ by 0.04 and whole lots are rejected at incoming inspection."],"answer":2,"explanation":"供應商與客戶的 MTF 量測台相差 0.04，整批在進料檢驗被退回；未設保護帶，邊緣件流入產品造成客訴；標準鏡在搬運中受損而讀值偏高，未被察覺下所有鏡頭都被高估。 需以量測區分可能原因。","explanationEn":"Supplier and customer MTF benches differ by 0.04 and whole lots are rejected at incoming inspection; without a guard band marginal parts reach products and return as complaints; a reference lens damaged in handling reads high unnoticed, so every lens is overestimated. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":44}],"order":7}],"scope":"公開原理的十二項教學任務，以自行繪製的示意模型、試算及來源資料進行；未提供工廠實測資料、專有配方或設備操作許可。","scopeEn":"Twelve educational tasks based on public principles, using original schematic models, calculations and referenced material. No factory measurement dataset, proprietary recipe or equipment operating authorization is supplied.","curriculumVersion":6,"enrichmentVersion":12,"v12Extension":{"stages":4,"steps":32,"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"焦點預算練習：f = 100 mm、f/4 的 N-BK7/F2 膠合雙合，f₁ = 43.3 mm、f₂ = −76.4 mm，搭配 3.45 µm 像素（Nyquist 145 lp/mm）。二級光譜使 C、F 焦點在 d 後 50 µm；把感測器放在中間 +25 µm，d、C、F 各離焦 25 µm，W₀₂₀ 為 0.33λ、0.30λ、0.40λ，Nyquist MTF 約 0.36、0.35、0.37，乘像素 sinc 0.64 後約 0.23。溫度上升 40 K：鏡片焦距伸長 100 × 1.53×10⁻⁶ × 40 = 6.1 µm，鋁鏡筒伸長 94.4 µm，失配 88 µm 遠超 ±17.6 µm 景深；改用 Invar 隔圈後殘差 1.3 µm。若改用 N-FK51A/N-KZFS4（f₁ = 47.3 mm、f₂ = −89.8 mm），色焦差降為 14.2 µm，置中後各色離焦 7.1 µm，Nyquist MTF 約 0.51 到 0.62，乘像素響應後約 0.33 到 0.39，足以通過 0.30 的規格。數值為教學假設，不代表任何實際產品規格。","textEn":"Focus-budget exercise: an f = 100 mm, f/4 cemented N-BK7/F2 doublet with f₁ = 43.3 mm and f₂ = −76.4 mm on 3.45 µm pixels (Nyquist 145 lp/mm). Secondary spectrum puts the C and F foci 50 µm behind d; placing the sensor midway at +25 µm defocuses d, C and F by 25 µm each, W₀₂₀ of 0.33λ, 0.30λ and 0.40λ, giving Nyquist MTF near 0.36, 0.35 and 0.37, about 0.23 after the 0.64 pixel sinc. A 40 K rise lengthens the lens focal length by 100 × 1.53×10⁻⁶ × 40 = 6.1 µm while an aluminium barrel grows 94.4 µm, an 88 µm mismatch far beyond the ±17.6 µm depth of focus; an Invar spacer leaves 1.3 µm. Switching to N-FK51A/N-KZFS4 (f₁ = 47.3 mm, f₂ = −89.8 mm) cuts the colour spread to 14.2 µm, so centred focus leaves each colour 7.1 µm out, Nyquist MTF about 0.51 to 0.62 and roughly 0.33 to 0.39 with the pixel response, enough to pass a 0.30 specification. Values are teaching assumptions, not any product's specification.","assumptions":"數值是本課自行設定的教學假設，不代表實機量測、產品額定或操作參數；改變系統邊界後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not measured hardware, product ratings or operating parameters; recalculate after changing the system boundary.","sourceScope":"原創數值練習；來源支援公開原理與設施背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and facility context, not these numbers."},"focus":"三片式複消色差、熱離焦、膠合與空氣間隔取捨、定心膠合工序、感測器匹配 MTF、波前與鬼影驗收","focusEn":"Three-glass apochromats, thermal defocus, cemented versus air-spaced trade-offs, centring and cementing, sensor-matched MTF, wavefront and ghost acceptance"},"learningTrack":"optics","learningSubdiscipline":"optics-design-fabrication","learningTags":["optics","optics-design-fabrication","imaging"],"subcategory":"optics-design-fabrication","subcategoryTitle":"光學設計與精密加工","subcategoryTitleEn":"Optical design and precision fabrication"}};
